import "server-only";
import { db } from "@/lib/db";
import { queryInfo, queryPlayers, gameVersionFromKeywords, type A2sInfo } from "@/lib/a2s";

/**
 * Nxeon community (free, public, shared) game servers — read side.
 *
 * One admin-managed table (FreePublicServer), no customer ownership, no
 * billing. Everything public is gated on `status === "LIVE" | "MAINTENANCE"`,
 * so with no row (or a PLANNED one) every surface that calls this stays
 * invisible: the feature is inert until the VM exists and an admin flips it on.
 *
 * Live state is a real Steam A2S query at read time and is NEVER persisted or
 * invented. States:
 *   online      the server answered A2S_INFO (players = its real count)
 *   unreachable the probe got no/garbled answer inside the timeout
 *   unknown     no probe result yet (first render under the page's time budget)
 */

export const PUBLIC_STATUSES = ["PLANNED", "LIVE", "MAINTENANCE", "RETIRED"] as const;
export type PublicStatus = (typeof PUBLIC_STATUSES)[number];
export const PASSWORD_POLICIES = ["OPEN", "PUBLISHED"] as const;

/** Statuses shown to players. PLANNED/RETIRED never leave the admin page. */
export const VISIBLE_STATUSES: PublicStatus[] = ["LIVE", "MAINTENANCE"];

export type FreePublicRow = NonNullable<Awaited<ReturnType<typeof db.freePublicServer.findFirst>>>;

/** DNS hostname only — the public address is never a raw IP. */
const HOST_RE = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
export function validHost(h: string): boolean {
  return HOST_RE.test(h) && !/^\d+(\.\d+){3}$/.test(h);
}
export function validPort(p: number): boolean {
  return Number.isInteger(p) && p >= 1024 && p <= 65534;
}

/** The row's public connect address as players type it: `host:port`. */
export function connectAddress(r: Pick<FreePublicRow, "host" | "port">): string {
  return `${r.host}:${r.port}`;
}

export async function listVisibleFreePublicServers(game?: string): Promise<FreePublicRow[]> {
  try {
    return await db.freePublicServer.findMany({
      where: { status: { in: VISIBLE_STATUSES }, ...(game ? { game } : {}) },
      orderBy: { createdAt: "asc" },
    });
  } catch {
    // Table not migrated yet (older deploy/staging DB): behave as "none exist".
    return [];
  }
}

export async function getVisibleFreePublicServer(slug: string): Promise<FreePublicRow | null> {
  try {
    return await db.freePublicServer.findFirst({ where: { slug, status: { in: VISIBLE_STATUSES } } });
  } catch {
    return null;
  }
}

export type LiveState =
  | { state: "online"; players: number; max: number | null; version: string | null; checkedAt: number }
  | { state: "unreachable"; checkedAt: number }
  | { state: "unknown" };

const TTL_MS = 20_000;
const cache = new Map<string, { at: number; value: LiveState }>();
const inflight = new Map<string, Promise<LiveState>>();

export function stateFromInfo(info: A2sInfo | null, now = Date.now()): LiveState {
  if (!info) return { state: "unreachable", checkedAt: now };
  const version = gameVersionFromKeywords(info.keywords) ?? (info.version && info.version !== "1.0.0.0" ? info.version : null);
  return { state: "online", players: info.players, max: info.maxPlayers, version, checkedAt: now };
}

async function probe(r: Pick<FreePublicRow, "id" | "host" | "queryPort">): Promise<LiveState> {
  const info = await queryInfo(r.host, r.queryPort, 1500);
  const v = stateFromInfo(info);
  cache.set(r.id, { at: Date.now(), value: v });
  return v;
}

function refresh(r: Pick<FreePublicRow, "id" | "host" | "queryPort">): Promise<LiveState> {
  let p = inflight.get(r.id);
  if (!p) {
    p = probe(r).finally(() => inflight.delete(r.id));
    inflight.set(r.id, p);
  }
  return p;
}

/**
 * Live state without ever blocking a page render for long. A fresh cache entry
 * is returned immediately; otherwise one probe runs (deduped across concurrent
 * renders) and we wait at most `budgetMs` for it — past that the last known
 * value (even if stale) or `unknown` is returned while the probe finishes in
 * the background to warm the cache for the next render.
 */
export async function liveState(r: Pick<FreePublicRow, "id" | "host" | "queryPort">, budgetMs = 1200): Promise<LiveState> {
  const hit = cache.get(r.id);
  if (hit && Date.now() - hit.at < TTL_MS) return hit.value;
  const p = refresh(r);
  const fallback: LiveState = hit?.value ?? { state: "unknown" };
  return Promise.race([p, new Promise<LiveState>((res) => { const t = setTimeout(() => res(fallback), budgetMs); t.unref?.(); })]);
}

/** Admin-side: force a fresh probe incl. the optional player list count. */
export async function probeNow(r: Pick<FreePublicRow, "id" | "host" | "queryPort">): Promise<{ live: LiveState; playerListCount: number | null }> {
  const live = await refresh(r);
  const list = live.state === "online" ? await queryPlayers(r.host, r.queryPort, 1500) : null;
  return { live, playerListCount: list ? list.length : null };
}

/** Test seam. */
export function _resetLiveCache() { cache.clear(); inflight.clear(); }
import "server-only";
