/**
 * /free-valheim-server — the Nxeon community Valheim server (free, public,
 * shared). The page exists only while an admin has the FreePublicServer row
 * (slug "valheim") at LIVE or MAINTENANCE; any other state 404s (fail closed),
 * which is also what keeps the whole feature inert until the VM exists.
 *
 * Real data only: address/password policy/region/capacity/rules are the row;
 * "online now" is a real Steam A2S answer (lib/free-public-server.ts) — absent,
 * never zero-as-fallback, when the server doesn't answer; the upgrade prices
 * are the real Valheim GamePlan rows.
 */
const SLUG = "valheim";
const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;

async function row(): Promise<FreePublicRow> {
  const r = await getVisibleFreePublicServer(SLUG);
  if (!r) notFound();
  return r;
}

function statusChip(r: FreePublicRow, l: LiveState) {
  if (r.status === "MAINTENANCE") return `<span class="au-chip fv-down"><i class="d"></i>Under maintenance</span>`;
  if (l.state === "online") return `<span class="au-chip fv-live"><i class="d"></i>Online now · ${l.players}${l.max ?? r.maxPlayers ? ` / ${l.max ?? r.maxPlayers}` : ""} playing</span>`;
  if (l.state === "unreachable") return `<span class="au-chip fv-down"><i class="d"></i>Not answering right now</span>`;
  return `<span class="au-chip fv-unk"><i class="d"></i>Checking status…</span>`;
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const r = await row();
  const [l, regions] = await Promise.all([liveState(r, 1500), deployRegions()]);
  const tiers = await realTiers(SLUG, regions.map((x) => x.code));
  const lo = tiers[0];
  const region = r.region ? regionLabel(r.region) : null;
  const addr = connectAddress(r);
  const hubHref = staged(gameRoute(SLUG) ?? "/game-servers");
  const upHref = lo ? deployHref({ service: "game", gameFamily: SLUG, gamePlanId: lo.id }) : hubHref;
  const published = r.passwordPolicy === "PUBLISHED" && r.passwordHint;
  const maxLine = `Up to ${r.maxPlayers} players`;

  const facts = [
    I("users") + `<span><b>${r.maxPlayers}</b> player slots</span>`,
    ...(region ? [I("globe") + `<span>Hosted in <b>${esc(region)}</b></span>`] : []),
    I("shield") + `<span>${published ? `Password rotated <b>${esc(r.rotation ?? "regularly")}</b>` : "No password"}</span>`,
    I("server") + `<span>UDP <b>${r.port}-${r.port + 2}</b></span>`,
  ].map((x) => `<li>${x}</li>`).join("");

  const steps: [string, string][] = [
    ["Start Valheim", "Launch the game on Steam, then pick or create a character. Your character lives on your own PC, so it goes with you."],
    ["Open Join Game", "Choose <b>Start Game</b>, select your character, then press <b>Join Game</b> and use the <b>Join IP</b> button."],
    ["Enter the address", `Type <b>${esc(addr)}</b> and press Connect.`],
    [published ? "Enter the password" : "Spawn in", published ? "When asked, paste the password shown at the top of this page and you will spawn into the world." : "You will spawn straight into the world."],
  ];

  const rules = [
    "<b>Do not grief.</b> Leave other players’ builds, chests and portals as you found them.",
    "<b>No cheats, exploits or duplication.</b> Use the game as it is meant to be played.",
    "<b>Keep chat friendly.</b> No harassment, slurs, spam or advertising.",
    "<b>Build where there is room.</b> Do not wall in the spawn or block paths and portals other players need.",
    "<b>Staff can remove players and builds</b> that break these rules, and banned players stay banned across password changes.",
  ];
  const run = [
    "<b>One shared world.</b> Everyone on the server plays in the same world; there are no private areas or protected plots.",
    "<b>No admin or console access for players.</b> You cannot ban, teleport or edit the world, and neither can anyone else you meet there.",
    `<b>${published ? "Rotating password." : "Open join."}</b> ${published ? `The password is published on this page and changed ${esc((r.rotation ?? "periodically").toLowerCase())}, so only people who visit this page can join.` : "No password is needed."}`,
    "<b>Daily backups.</b> The world is backed up every day and recent backups are kept, so ordinary mishaps can be rolled back.",
    ...(r.wipePolicy ? [`<b>Resets.</b> ${esc(r.wipePolicy)}`] : []),
    "<b>Best-effort, not guaranteed.</b> It is a free shared server: it may restart for game updates or maintenance.",
  ];

  const upList = [
    `A private world with your own password${lo?.slots ? `, for ${tiers.map((t) => t.slots).filter(Boolean).join(" or ")} players` : ""}`,
    "Admin list, world modifiers and a full control panel",
    "Mod support (BepInEx), automatic backups and crossplay switch",
  ].map((x) => `<li>${esc(x)}</li>`).join("");

  const faq: [string, string][] = [
    ["Is this server really free?", "Yes. There is no card, no sign-up and no payment step: copy the address and join. It is a shared community server that Nxeon runs, and it can be reset (see the rules above)."],
    ["How many people can play at once?", `${maxLine}. If it is full, try again in a few minutes, or get your own private world.`],
    ["Why is there a password?", published ? `Valheim servers need one. We publish it on this page and change it ${(r.rotation ?? "regularly").toLowerCase()}, which keeps bots and passers-by out while anyone who visits this page can still join.` : "There is no password on this server."],
    ["Will I lose my character?", "No. Valheim stores your character on your own computer. The world is stored on the server."],
    ["Can I use mods, commands or admin tools here?", "No. This is a plain shared world with no admin access for players. For mods and full control, get your own server."],
    ["What happens if the world gets griefed?", r.wipePolicy ?? "Staff can roll the world back from a daily backup or reset it, and remove players who break the rules."],
    ["Can I join from console?", "This server is set up for PC players who join by IP address. Console crossplay is not enabled here."],
    ["How do I get my own Valheim world?", lo ? `Order a private Valheim server from ${money(lo.i ?? lo.p)} a month. It is live in minutes with your own password and admin controls.` : "See our Valheim server plans."],
    ["Is this affiliated with the makers of Valheim?", "No. Valheim is made by Iron Gate Studio and published by Coffee Stain Publishing. Nxeon runs this server independently."],
  ];

  const art = gameArt(SLUG).hero;
  const ctas = btn(true, upHref, lo ? `Get your own world from ${money(lo.i ?? lo.p)}/mo` : "See Valheim plans")
    + `<a class="nxm-glassbtn" href="${esc(nxmHref("/game-servers/directory"))}"><span class="nxm-bt">Browse the server directory</span></a>`;

  return {
    slots: {
      "art.style": art ? `background-image:url('${esc(art)}')` : "",
      "status:html": statusChip(r, l),
      h1a: "Free Valheim server.", h1b: "Join in seconds.",
      sub: r.tagline ? `${r.tagline} Run by Nxeon: no sign-up, no card, just copy the address into Join IP.` : "A free public Valheim world run by Nxeon: no sign-up, no card, just copy the address into Join IP.",
      address: addr,
      "password:html": published
        ? `<div class="fv-box au-glass"><span class="fv-l">Password${r.rotation ? ` (changes ${esc(r.rotation.toLowerCase())})` : ""}</span><code>${esc(r.passwordHint!)}</code><button type="button" class="dr-copy" data-copy="${esc(r.passwordHint!)}"><span class="nxm-bt">Copy</span></button></div>`
        : `<div class="fv-box au-glass"><span class="fv-l">Password</span><code>None needed</code></div>`,
      "facts:html": facts,
      "hero.ctas:html": ctas,
      "steps:html": steps.map(([h, t], i) => `<li class="au-card"><span class="n">0${i + 1}</span><h3>${esc(h)}</h3><p>${t}</p></li>`).join(""),
      "join.note": "This server is unlisted on purpose, so Join IP is the way in. If the game says the version is incompatible, update Valheim from Steam and try again.",
      "rules:html": rules.map((x) => `<li>${x}</li>`).join(""),
      "run:html": run.map((x) => `<li>${x}</li>`).join(""),
      "up.h": lo ? `Your own ${gameName(SLUG)} world, from ${money(lo.i ?? lo.p)} a month` : `Your own ${gameName(SLUG)} world`,
      "up.p": "A shared world is great for a quick visit. When you want your friends, your rules and your own save, a private server takes a couple of minutes to set up.",
      "up.list:html": upList,
      "up.cta:html": (lo ? `<p class="fv-up-price">From<b>${money(lo.i ?? lo.p)}<small style="font-size:.9rem;font-weight:600"> / month</small></b>${lo.slots ? `${lo.slots} players, ${lo.ram} GB` : ""}</p>` : "")
        + btn(true, upHref, "Get a private server") + btn(false, hubHref, "See all Valheim plans"),
      "faq.lede": supportLine(),
      "faq:html": faq.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join(""),
      "final:html": btn(true, upHref, "Get your own world") + `<a class="nxm-glassbtn" href="${esc(nxmHref("/game-servers/directory"))}"><span class="nxm-bt">Browse the directory</span></a>`,
    },
    data: { address: addr },
    jsonLd: [{
      "@context": "https://schema.org", "@type": "Product", name: "Nxeon Community Valheim Server",
      description: "A free public Valheim server run by Nxeon. No sign-up and no card: join by IP address.",
      brand: { "@type": "Brand", name: "Nxeon" },
      offers: { "@type": "Offer", price: "0", priceCurrency: "USD", availability: "https://schema.org/InStock", url: `${APP_URL}/free-valheim-server` },
    }],
    particles: { from: "#8a70fb", to: "#22d3ee" },
    crumb: "Free Valheim server",
    trail: [{ name: "Game servers", path: "/game-servers" }],
  };
}

export async function meta(_p: Record<string, string>) {
  const r = await row();
  return {
    title: "Free Valheim Server: Join Now, No Sign-Up",
    description: `Join a free public Valheim server run by Nxeon. Copy the address, use Join IP${r.passwordPolicy === "PUBLISHED" ? ", enter the published password" : ""} and play. No card, no account. Upgrade to your own private world anytime.`,
    image: gameArt(SLUG).hero ?? undefined,
  };
}

