 * - /servers (view "free"): free Minecraft servers whose owner made them
 *   public (FreeMinecraftServer isPublic + READY), newest first, capped at the
 *   live page's 48; each links to its own page (/servers/<subdomain>).
 *   Address domain = Setting free_minecraft_domain (the live fallback).
 * - /game-servers/directory (view "all"): paid game servers with public
 *   listing on (Server publicListing + RUNNING + a game plan + a subdomain —
 *   never a raw IP) plus the public free servers; paid first, then by name.
 *   Address domain = lib/game-subdomain-dns gameSubdomainBase().
 *
 * No player counts here (like the live page: one SSH round trip per listed
 * server on a public page would let a slow host take the directory down);
 * the server's own page shows its live status.
 */
const CAP = 48;
const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;

export type Entry = {
  key: string; name: string; tagline: string; desc: string; mode: string; family: string; filter: string; filterLabel: string;
  address: string; free: boolean; slots: number | null; href: string | null;
  /** Nxeon-operated community server (FreePublicServer), shown first. */
  community?: boolean;
  /** Real A2S state: players online, null when the server did not answer. */
  live?: { state: "online" | "unreachable" | "unknown"; players: number | null };
  region?: string | null; password?: string | null;
};

async function entries(view: "free" | "all"): Promise<{ list: Entry[]; domain: string }> {
  const freeRow = (s: { subdomain: string; name: string | null; activeGameType: string; publicTagline: string | null; publicDescription?: string | null }, domain: string, withDesc: boolean): Entry => {
    const preset = FREEMC_GAME_TYPES[s.activeGameType] ?? FREEMC_GAME_TYPES.vanilla;
    return {
      key: `f-${s.subdomain}`, name: s.name || s.subdomain,
      tagline: (withDesc ? s.publicTagline || s.publicDescription : s.publicTagline) || "",
      desc: preset.description, mode: preset.label, family: "minecraft",
      filter: `mc-${s.activeGameType}`, filterLabel: preset.label,
      address: `${s.subdomain}.${domain}`, free: true, slots: null, href: nxmHref(`/servers/${s.subdomain}`),
    };
  };
  if (view === "free") {
    const [domain, rows] = await Promise.all([
      getSetting("free_minecraft_domain", "play.nxeon.cloud"),
      db.freeMinecraftServer.findMany({
        where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "desc" }, take: CAP,
        select: { subdomain: true, name: true, activeGameType: true, publicTagline: true },
      }),
    ]);
    return { domain, list: rows.map((s) => freeRow(s, domain, false)) };
  }
  const [domain, paid, free] = await Promise.all([
    gameSubdomainBase(),
    db.server.findMany({
      where: { publicListing: true, status: "RUNNING", gamePlan: { isNot: null }, subdomain: { not: null } },
      select: { id: true, name: true, label: true, publicDescription: true, subdomain: true, gamePlan: { select: { slots: true, gameFamily: true } } },
      orderBy: { createdAt: "asc" },
    }),
    db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "asc" },
      select: { subdomain: true, name: true, activeGameType: true, publicTagline: true, publicDescription: true },
    }),
  ]);
  const list: Entry[] = paid.filter((s) => s.subdomain).map((s) => {
    const family = s.gamePlan?.gameFamily ?? "minecraft";
    return {
      key: `p-${s.id.slice(0, 8)}`, name: s.label || s.name, tagline: s.publicDescription ?? "", desc: "",
      mode: gameName(family), family, filter: family, filterLabel: gameName(family),
      address: `${s.subdomain}.${domain}`, free: false, slots: s.gamePlan?.slots ?? null, href: null,
    };
  });
  for (const s of free) list.push({ ...freeRow(s, domain, true), filter: "minecraft", filterLabel: gameName("minecraft") });
  list.sort((a, b) => (a.free !== b.free ? (a.free ? 1 : -1) : a.name.localeCompare(b.name)));
  // Nxeon community servers (admin-managed, only LIVE/MAINTENANCE rows) lead the
  // list. Live player counts are real A2S answers inside a short budget, never faked.
  const community = await listVisibleFreePublicServers();
  const comm: Entry[] = await Promise.all(community.map(async (c) => {
    const l = await liveState(c, 1200);
    return {
      key: `c-${c.slug}`, name: c.name, tagline: c.tagline ?? "", desc: "Free, public and run by Nxeon. No account needed to join.",
      mode: gameName(c.game), family: c.game, filter: "community", filterLabel: "Nxeon community",
      address: connectAddress(c), free: true, slots: c.maxPlayers, href: nxmHref(`/free-${c.game}-server`),
      community: true, region: c.region ? regionLabel(c.region) : null,
      live: l.state === "online" ? { state: "online", players: l.players } : { state: l.state, players: null },
    } satisfies Entry;
  }));
  return { domain, list: [...comm, ...list] };
}

/** One listing card (exported for visual checks with sample rows). */
export function card(e: Entry) {
  const art = gameArt(e.family).cover;
  const q = [e.name, e.tagline, e.desc, e.mode, e.address].join(" ").toLowerCase();
  const meta = e.community
    ? [e.live?.state === "online" ? `${e.live.players} online now` : e.live?.state === "unreachable" ? "Not answering right now" : "", e.slots != null ? `Up to ${e.slots} players` : "", e.region ?? ""].filter(Boolean)
    : e.slots != null ? [`Recommended for ${e.slots} players`] : [];
  return `<article class="au-card dr-card" data-q="${esc(q)}" data-f="${esc(e.filter)}">`
    + `<div class="dr-top">${art ? `<img class="dr-ic" src="${esc(art)}" alt="" width="46" height="62" loading="lazy">` : ""}<div><h3 title="${esc(e.name)}">${esc(e.name)}</h3><span class="dr-mode">${esc(e.mode)}</span></div>${e.community ? `<span class="dr-badge c">Nxeon community</span>` : e.free ? `<span class="dr-badge">Free tier</span>` : `<span class="dr-badge p">Running</span>`}</div>`
    + (e.tagline ? `<p class="dr-tag">${esc(e.tagline)}</p>` : "")
    + (e.desc ? `<p class="dr-desc">${esc(e.desc)}</p>` : "")
    + (meta.length && (!e.free || e.community) ? `<div class="dr-meta">${meta.map((m) => `<span>${esc(m)}</span>`).join("")}</div>` : "")
    + `<div class="dr-addr"><code title="${esc(e.address)}">${esc(e.address)}</code><button type="button" class="dr-copy" data-copy="${esc(e.address)}">Copy</button></div>`
    + (e.href ? `<a class="dr-go" href="${esc(e.href)}">${e.community ? "How to join" : "View server"} <span aria-hidden="true">→</span></a>` : "")
    + `</article>`;
}

const SEARCH = `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>`;

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const view = p.view === "all" ? "all" : p.view === "free" ? "free" : null;
  if (!view) notFound();
  const { list, domain } = await entries(view);
  const n = list.length, paid = list.filter((e) => !e.free).length, nComm = list.filter((e) => e.community).length;
  const createFree = btn(true, "/dashboard/free-minecraft", "Create my free server");

  // mode / game filter chips from what is actually listed
  const groups = new Map<string, { label: string; n: number }>();
  for (const e of list) groups.set(e.filter, { label: e.filterLabel, n: (groups.get(e.filter)?.n ?? 0) + 1 });
  const chips = groups.size > 1
    ? `<div class="dr-chips" role="group" aria-label="Filter"><button type="button" data-f="" aria-pressed="true">All<b>${n}</b></button>${[...groups].sort((a, b) => b[1].n - a[1].n).map(([f, g]) => `<button type="button" data-f="${esc(f)}" aria-pressed="false">${esc(g.label)}<b>${g.n}</b></button>`).join("")}</div>`
    : "";
  const tools = n
    ? `<div class="dr-tools"><label class="dr-search">${SEARCH}<span class="visually-hidden">Search servers</span><input id="dr-q" type="search" placeholder="Search by name, tagline or game mode" autocomplete="off"></label>${chips}<p class="dr-count" id="dr-count" aria-live="polite">${n} server${n === 1 ? "" : "s"}</p></div>`
    : "";
  const empty = view === "free"
    ? `<div class="au-card dr-empty"><span class="au-tile">${I("server")}</span><h3>No public servers yet</h3><p>Be the first: create a free server and turn on public listing from its Manage tab.</p>${createFree}</div>`
    : `<div class="au-card dr-empty"><span class="au-tile">${I("server")}</span><h3>No servers listed yet</h3><p>Be the first to list your server in the directory.</p>${btn(true, nxmHref("/free-minecraft"), "Get your free server")}</div>`;

  const facts = `<li>${I("server")}<b>${n}</b> listed now</li>`
    + (view === "all" ? `<li>${I("game")}<b>${paid}</b> paid · <b>${n - paid - nComm}</b> free${nComm ? ` · <b>${nComm}</b> Nxeon community` : ""}</li>` : "")
    + `<li>${I("globe")}Addresses on <b>*.${esc(domain)}</b></li><li>${I("users")}No account needed to join</li>`;

  const faq: [string, string][] = [
    ["Do I need an account to join a server?", "No. Copy a server’s address and connect from Minecraft. You only need an account to run a server of your own."],
    ["How do I list my own server here?", view === "free"
      ? "Create a free Minecraft server, then turn on public listing from its Manage tab. It appears here as soon as it’s ready."
      : "Free server: turn on public listing from its Manage tab. Paid game server: switch on the Public Directory card in the game panel’s Settings tab and add a description. A listed paid server shows here while it’s running."],
    ["How is the list ordered?", view === "free"
      ? "Newest first. Nothing here is curated or ranked; names, taglines and game modes come from each server’s owner."
      : "Paid servers first, then free ones, each alphabetically. Nothing here is curated or ranked; names and descriptions come from each server’s owner."],
    ["Why does a free server take a moment to respond?", "Free servers sleep when nobody is playing. Connecting wakes the server up, and it’s back within seconds."],
    ["Are server addresses safe to share?", "Every listing shows a subdomain, never a raw IP address, and a server leaves the directory the moment its owner turns listing off."],
  ];

  const itemList = n ? [{
    "@context": "https://schema.org", "@type": "CollectionPage",
    name: view === "free" ? "Public Minecraft server directory" : "Public game server directory",
    url: APP_URL + (view === "free" ? "/servers" : "/game-servers/directory"),
    mainEntity: {
      "@type": "ItemList", numberOfItems: n,
      itemListElement: list.slice(0, 48).map((e, i) => ({
        "@type": "ListItem", position: i + 1, name: e.name,
        ...(e.href ? { url: e.community ? `${APP_URL}${e.href.replace(/^\/nxm/, "")}` : `${APP_URL}/servers/${e.address.split(".")[0]}` } : {}),
      })),
    },
  }] : [];

  return {
    slots: {
      "hero.chip": view === "free" ? "Public directory" : "Server directory",
      "hero.h1a": view === "free" ? "Public Minecraft servers." : "Community servers,",
      "hero.h1b": view === "free" ? "Pick one, connect now." : "hosted on Nxeon.",
      "hero.sub": view === "free"
        ? "Every server below is a real free Nxeon server whose owner opted in to be listed. No account needed to join: copy the address and connect."
        : "Browse community servers hosted on Nxeon. Find your next world, copy the address, and start playing.",
      "hero.ctas:html": (view === "free" ? createFree : btn(true, nxmHref("/free-minecraft"), "Get your free server"))
        + `<a class="nxm-glassbtn" href="${esc(nxmHref("/game-servers"))}"><span class="nxm-bt">${view === "free" ? "Need more power? See paid servers" : "See all game plans"}</span></a>`,
      "facts:html": facts,
      "list.h": view === "free" ? "Browse the directory" : "Every public server",
      "list.lede": view === "free"
        ? "Owner-submitted taglines and game modes. Nothing here is curated or ranked, just newest first."
        : "Paid servers first, then free ones. Names and descriptions are written by each server’s owner.",
      "tools:html": tools,
      "grid:html": n ? list.map(card).join("") : empty,
      "steps.h": "List your own server here",
      "steps.lede": "Owners choose to be listed, and can switch it off at any time.",
      "steps:html": (view === "free"
        ? [["Create a free server", `No credit card. Pick a name and it’s live at yourworld.${domain}.`],
           ["Turn on public listing", "Open your server’s Manage tab, switch public listing on and add a tagline."],
           ["Players find you here", "Your server appears in this directory as soon as it’s ready, its address one click from copied."]]
        : [["Free Minecraft server", "Turn on public listing from its Manage tab. It shows here as soon as it’s ready."],
           ["Paid game server", "Switch on the Public Directory card in the game panel’s Settings tab and add a description."],
           ["Players find you here", "Listed servers show their subdomain address, never a raw IP, one click from copied."]])
        .map(([h, t], i) => `<li class="au-card"><span class="n">0${i + 1}</span><h3>${esc(h)}</h3><p>${esc(t)}</p></li>`).join(""),
      "faq.lede": supportLine(),
      "faq:html": faq.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join(""),
      "final.h": view === "free" ? "Get your own free Minecraft server" : "Host your own server for free",
      "final.p": view === "free"
        ? "No credit card, live in under a minute, and you can list it here the moment it’s ready."
        : "Get a free Minecraft server with your own subdomain, mod menu, and full control panel. List it here for others to find.",
      "final:html": (view === "free" ? createFree : btn(true, nxmHref("/free-minecraft"), "Get your free server"))
        + `<a class="nxm-glassbtn" href="${esc(nxmHref(view === "free" ? "/free-minecraft" : "/game-servers"))}"><span class="nxm-bt">${view === "free" ? "Learn how it works" : "See all game plans"}</span></a>`,
    },
    jsonLd: itemList,
    crumb: "Server directory",
  };
}

export async function meta(p: Record<string, string>) {
  if (p.view !== "all" && p.view !== "free") notFound();
  return { image: gameArt("minecraft").hero ?? undefined };
}
