const inflight: Map<string, number> = (g.__nxFilesInflight ??= new Map());

/** Record `n` bytes for a user; false when that would exceed the per-minute budget. */
function takeBytes(userId: string, n: number): boolean {
  const now = Date.now();
  const log = (byteLog.get(userId) ?? []).filter((x) => now - x.t < 60_000);
  const used = log.reduce((a, x) => a + x.n, 0);
  if (used + n > UPLOAD_BYTES_PER_MIN) { byteLog.set(userId, log); return false; }
  log.push({ t: now, n });
  byteLog.set(userId, log);
  return true;
}

