async function handleUpload(
  req: NextRequest,
  server: SftpServer,
  userId: string,
  dir: string
): Promise<NextResponse> {
  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
  }

  // Folder uploads: `relPath` is the path of the file (or, with `mkdir=1`, the
  // empty directory) relative to `dir`, e.g. "ModLib/lib/a.jar". Validated by
  // the same parseRelPath the browser uses, then re-normalized under `dir`.
  const relRaw = form.get("relPath");
  const mkdirOnly = form.get("mkdir") === "1";
  let relSegs: string[] = [];
  if (relRaw !== null && relRaw !== "") {
    try {
      relSegs = parseRelPath(relRaw, mkdirOnly ? "dir" : "file");
    } catch (err) {
      return NextResponse.json(
        { error: err instanceof Error ? err.message : "invalid path" },
        { status: 400 }
      );
    }
  } else if (mkdirOnly) {
    return NextResponse.json({ error: "a relative path is required" }, { status: 400 });
  }

  if (mkdirOnly) {
    try {
      const target = joinPath(dir, relSegs.join("/"));
      await mkdirpPath(server, target);
      return NextResponse.json({ ok: true, path: target });
    } catch (err) {
      const msg = err instanceof Error ? err.message : "mkdir failed";
      return NextResponse.json({ error: msg }, { status: /Invalid|exists/i.test(msg) ? 400 : 502 });
    }
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "no file provided" }, { status: 400 });
  }
  if (file.size > MAX_UPLOAD_BYTES) {
    return NextResponse.json(
      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
      { status: 413 }
    );
  }
  if (!takeBytes(userId, file.size)) {
    return NextResponse.json(
      { error: "upload volume limit reached — wait a minute and retry", retryAfterSec: 30 },
      { status: 429, headers: { "Retry-After": "30" } }
    );
  }

  let target: string;
  let targetDir = dir;
  try {
    if (relSegs.length > 0) {
      const name = validateName(relSegs[relSegs.length - 1]);
      targetDir = joinPath(dir, relSegs.slice(0, -1).join("/"));
      target = joinPath(targetDir, name);
    } else {
      const name = validateName((file.name || "upload").trim());
      target = joinPath(dir, name);
    }
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid filename" },
      { status: 400 }
    );
  }

  try {
    const data = Buffer.from(await file.arrayBuffer());
    // Re-check the actual byte length in case the reported size was understated.
    if (data.length > MAX_UPLOAD_BYTES) {
      return NextResponse.json({ error: "file too large" }, { status: 413 });
    }
    // Create the destination directory (and, for folder uploads, any missing
    // parents — mkdir -p). The file manager normally targets an existing dir
    // (harmless no-op), but the Matrix console uploads into ~/nxeon-uploads,
    // which may not exist yet, and client.put() does not create parent dirs.
    try {
      if (relSegs.length > 1) await mkdirpPath(server, targetDir);
      else await mkdirPath(server, dir);
    } catch {
      /* already exists / benign — the write below surfaces any real failure */
    }
    await writeFileBuffer(server, target, data);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "upload failed";
    const status = /Invalid|directory/i.test(msg) ? 400 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  return NextResponse.json({ ok: true, path: target });
}
