import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard, Badge, EmptyState } from "@/components/ui/primitives";
import { FreePublicServerForm, FreePublicRowActions, VALHEIM_DEFAULTS } from "@/components/admin/FreePublicServerControls";

export const dynamic = "force-dynamic";

/**
 * Admin tile for Nxeon community servers (free, public, shared). Live state is
 * checked on demand (Probe now = one real A2S query), never swept on page load.
 * Nothing here is visible to the public until a row is set to LIVE.
 */
export default async function AdminFreeServers() {
  await requireArea("fleet");
  const rows = await db.freePublicServer.findMany({ orderBy: { createdAt: "asc" } }).catch(() => null);
  if (rows === null) {
    return <div className="space-y-6"><PageHeader title="Community servers" sub="Free public shared servers." /><EmptyState title="Table not migrated" sub="Run prisma db push on this database to enable community servers." /></div>;
  }
  const since = (d: number) => new Date(Date.now() - d * 86400_000);
  const stats = new Map<string, { n: number; up: number; peak24: number | null; peak7: number | null }>();
  for (const r of rows) {
    const smp = await db.freePublicServerSample.findMany({ where: { serverId: r.id, at: { gte: since(7) } }, select: { at: true, online: true, players: true } }).catch(() => []);
    const peak = (from: Date) => smp.filter((x) => x.at >= from && x.players != null).reduce<number | null>((m, x) => (m == null || x.players! > m ? x.players! : m), null);
    stats.set(r.id, { n: smp.length, up: smp.filter((x) => x.online).length, peak24: peak(since(1)), peak7: peak(since(7)) });
  }
  const live = rows.filter((r) => r.status === "LIVE").length;
  const hasValheim = rows.some((r) => r.slug === "valheim");
  return (
    <div className="space-y-6">
      <PageHeader title="Community servers" sub="Nxeon-run free public shared game servers. Hidden from every public page until set LIVE." />
      <div className="grid gap-4 sm:grid-cols-3">
        <StatCard label="Servers" value={String(rows.length)} />
        <StatCard label="Live" value={String(live)} />
        <StatCard label="Planned" value={String(rows.filter((r) => r.status === "PLANNED").length)} />
      </div>
      {rows.map((r) => (
        <div key={r.id} className="card space-y-4 p-4">
          <div className="flex flex-wrap items-center gap-2">
            <h2 className="text-base font-semibold">{r.name}</h2>
            <Badge tone={r.status === "LIVE" ? "green" : r.status === "MAINTENANCE" ? "amber" : "slate"}>{r.status}</Badge>
            <span className="font-mono text-xs text-slate-400">{r.host}:{r.port} (query {r.queryPort})</span>
          </div>
          {(() => { const st = stats.get(r.id)!; return st.n ? (
            <p className="text-xs text-slate-400">Last 7 days ({st.n} probes): answered {Math.round((st.up / st.n) * 100)}% of the time · peak players {st.peak7 ?? "n/a"} (24h: {st.peak24 ?? "n/a"})</p>
          ) : <p className="text-xs text-slate-500">No probe history yet. Enable the 5-minute timer with --record (see the plan doc) to measure peak players and uptime.</p>; })()}
          <FreePublicRowActions id={r.id} status={r.status} policy={r.passwordPolicy} />
          <details><summary className="cursor-pointer text-xs text-slate-400">Edit settings</summary>
            <div className="mt-3"><FreePublicServerForm row={r} /></div>
          </details>
        </div>
      ))}
      {!hasValheim && (
        <div className="card p-4">
          <h2 className="section-label mb-2">Add the community Valheim server</h2>
          <p className="mb-3 text-xs text-slate-400">Prefilled with the planned values. Leave status PLANNED until the VM is up and the probe answers.</p>
          <FreePublicServerForm row={VALHEIM_DEFAULTS} isNew />
        </div>
      )}
      <div className="card p-4 text-xs text-slate-400">Setup steps: docs/PLAN-FREE-VALHEIM.md and scripts/provision-public-valheim.sh.</div>
    </div>
  );
}

