/// Optional extras for an OPTED-IN public listing, plus moderation. A listing
/// with no row here is visible exactly as before. `tagline` is plain text shown
/// on the card; `imageUrl` / `websiteUrl` are customer-supplied https URLs that
/// are NEVER rendered until an admin sets `mediaApproved` (so a stranger's
/// image or link cannot appear on a public page unreviewed). `hidden` is the
/// admin kill switch (also hides the listing from the dashboard directory);
/// `featured` is the admin's "Featured servers" pick.
model PublicListingMeta {
  serverId      String   @id
  server        Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  tagline       String?
  imageUrl      String?
  websiteUrl    String?
  mediaApproved Boolean  @default(false)
  hidden        Boolean  @default(false)
  featured      Boolean  @default(false)
  moderatedById String?
  moderatedAt   DateTime?
  moderationNote String?
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt

