/**
 * Health probe for Nxeon community servers (FreePublicServer rows).
 *
 *   npx tsx scripts/probe-free-public-servers.ts          # human lines, exit 1 if any LIVE server is down
 *   npx tsx scripts/probe-free-public-servers.ts --json
 *   npx tsx scripts/probe-free-public-servers.ts --record  # also store each result as a FreePublicServerSample
 *                                                          # (and prune samples older than 90 days)
 *
 * Read-only: one real Steam A2S_INFO per LIVE/MAINTENANCE row to its public
 * host:queryPort (the same packet a game client sends) and nothing else. Meant
 * for a systemd timer with OnFailure=alert-admins (see docs/PLAN-FREE-VALHEIM.md);
 * the admin tile (/admin/free-servers "Probe now") runs the same query on demand.
 */
import { PrismaClient } from "@prisma/client";
import { queryInfo, gameVersionFromKeywords } from "../lib/a2s";

async function main() {
  const json = process.argv.includes("--json");
  const db = new PrismaClient();
  try {
    const rows = await db.freePublicServer.findMany({ where: { status: { in: ["LIVE", "MAINTENANCE"] } } });
    const record = process.argv.includes("--record");
    const out = [];
    let down = 0;
    for (const r of rows) {
      const i = await queryInfo(r.host, r.queryPort, 2500);
      const up = !!i;
      if (!up && r.status === "LIVE") down++;
      if (record) await db.freePublicServerSample.create({ data: { serverId: r.id, online: up, players: i ? i.players : null } });
      out.push({ slug: r.slug, status: r.status, address: `${r.host}:${r.port}`, up, players: i?.players ?? null, max: i?.maxPlayers ?? null, gameVersion: i ? gameVersionFromKeywords(i.keywords) : null });
    }
    if (record) await db.freePublicServerSample.deleteMany({ where: { at: { lt: new Date(Date.now() - 90 * 86400_000) } } });
    if (json) console.log(JSON.stringify(out));
    else for (const o of out) console.log(`${o.up ? "UP  " : "DOWN"} ${o.slug} ${o.address} [${o.status}]${o.up ? ` players=${o.players}/${o.max ?? "?"}${o.gameVersion ? ` game=${o.gameVersion}` : ""}` : ""}`);
    if (!rows.length && !json) console.log("no LIVE/MAINTENANCE community servers");
    process.exitCode = down ? 1 : 0;
  } finally {
    await db.$disconnect();
  }
}
