import "server-only";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { FREEMC_GAME_TYPES } from "@/lib/free-minecraft-control";
import { APP_URL } from "@/components/marketing/StructuredData";
import { loadDirectory } from "@/lib/server-directory-data";
import { groupByGame, pickFeatured, indexableGamePage, type DirEntry } from "@/lib/server-directory";
import { btn } from "./cards";
import { esc, nxmHref, type NxmLoad } from "./lib";
import { gameArt, gameName, gameRoute, isGameFamily, staged } from "./games-lib";
import { supportLine } from "./products-common";

/**
 * The public server directory — three views of one template:
 *
 * - /servers (view "free"): free Minecraft servers whose owner made them
 *   public (FreeMinecraftServer isPublic + READY), newest first, capped at 48;
 *   each links to its own page (/servers/<subdomain>).
 * - /game-servers/directory (view "all"): the homepage. A Featured shelf, a
 *   cover tile per game that has listings, then the best servers across all
 *   games (image first, Nxeon-hosted next, busiest after).
 * - /game-servers/directory/<game> (view "game"): every server for one game.
 *   Indexable only when enough described, recently seen servers back it
 *   (lib/server-directory.ts indexableGamePage); empty or thin pages are noindex.
 *
 * Sources (lib/server-directory-data.ts): customers' paid servers that opted
 * in, free Minecraft servers that opted in, Nxeon community servers and — only
 * when an admin enabled it — servers ingested from the Steam list. Nxeon-hosted
 * entries wear the Nxeon badge; duplicates by domain / ip / ip:port collapse
 * (see lib/server-directory.ts for the exact rule).
 *
 * No live player counts are probed here (one network round trip per listed
 * server on a public page would let one slow host take the directory down):
 * counts shown are the community server's own live answer and the figure an
 * ingested server had when it was last collected.
 */
const CAP_HOME = 24;
const CAP_GAME = 120;
const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;

async function freeMinecraftEntries(): Promise<{ list: DirEntry[]; domain: string }> {
  const [domain, rows] = await Promise.all([
    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
    db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "desc" }, take: 48,
      select: { subdomain: true, name: true, activeGameType: true, publicTagline: true },
    }),
  ]);
  return {
    domain,
    list: rows.map((s): DirEntry => {
      const preset = FREEMC_GAME_TYPES[s.activeGameType] ?? FREEMC_GAME_TYPES.vanilla;
      const host = `${s.subdomain}.${domain}`;
      return {
        key: `f-${s.subdomain}`, source: "nxeon-free", nxeon: true, game: "minecraft",
        name: s.name || s.subdomain, tagline: s.publicTagline ?? "", description: preset.description,
        imageUrl: null, address: host, host, port: null, alsoKeys: [], players: null, maxPlayers: null,
        country: null, region: null, featured: false, href: nxmHref(`/servers/${s.subdomain}`), websiteUrl: null, seenAt: null,
        // the free view's filter is the game mode, carried in `region` for the chip label below
      } satisfies DirEntry;
    }).map((e, i) => ({ ...e, region: FREEMC_GAME_TYPES[rows[i].activeGameType]?.label ?? FREEMC_GAME_TYPES.vanilla.label })),
  };
}

const filterTokens = (e: DirEntry, mode?: string) =>
  [e.nxeon ? "nx" : "ext", e.imageUrl ? "img" : "", mode ?? ""].filter(Boolean).join(" ");

/** One listing card (exported for visual checks with sample rows). */
export function card(e: DirEntry, opts: { mode?: string } = {}) {
  const art = gameArt(e.game).cover;
  const q = [e.name, e.tagline, e.description, gameName(e.game), e.address].join(" ").toLowerCase();
  const badge = e.nxeon
    ? `<span class="dr-badge nx" title="Hosted on Nxeon">${I("shield")}Nxeon</span>`
    : `<span class="dr-badge x" title="Found on a public server list">Public list</span>`;
  const meta = [
    e.players != null ? `${e.players}${e.maxPlayers ? ` / ${e.maxPlayers}` : ""} playing` : e.maxPlayers ? `Up to ${e.maxPlayers} players` : "",
    e.region ?? "", e.country ?? "",
  ].filter(Boolean);
  const head = e.imageUrl
    ? `<div class="dr-banner"><img src="${esc(e.imageUrl)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" width="640" height="320"></div>`
    : "";
  const link = e.websiteUrl ? `<a class="dr-go" href="${esc(e.websiteUrl)}" rel="ugc nofollow noopener noreferrer" target="_blank">Website <span aria-hidden="true">↗</span></a>` : "";
  return `<article class="au-card dr-card${e.imageUrl ? " has-img" : ""}" data-q="${esc(q)}" data-f="${esc(filterTokens(e, opts.mode))}">`
    + head
    + `<div class="dr-top">${art ? `<img class="dr-ic" src="${esc(art)}" alt="" width="46" height="62" loading="lazy">` : ""}<div><h3 title="${esc(e.name)}">${esc(e.name)}</h3><span class="dr-mode">${esc(gameName(e.game))}</span></div>${badge}</div>`
    + (e.tagline ? `<p class="dr-tag">${esc(e.tagline)}</p>` : "")
    + (e.description ? `<p class="dr-desc">${esc(e.description)}</p>` : "")
    + (meta.length ? `<div class="dr-meta">${meta.map((m) => `<span>${esc(m)}</span>`).join("")}</div>` : "")
    + `<div class="dr-addr"><code title="${esc(e.address)}">${esc(e.address)}</code><button type="button" class="dr-copy" data-copy="${esc(e.address)}">Copy</button></div>`
    + (e.href ? `<a class="dr-go" href="${esc(nxmHref(e.href))}">${e.source === "nxeon-community" ? "How to join" : "View server"} <span aria-hidden="true">→</span></a>` : "")
    + link
    + `</article>`;
}

function featuredSection(list: DirEntry[]): string {
  const f = pickFeatured(list, 6);
  if (!f.length) return "";
  return `<section class="section dr-feat" id="featured" aria-labelledby="ft-title" style="padding-bottom:0"><div class="container">`
    + `<div class="gp-head"><div><h2 class="h2" id="ft-title">Featured servers</h2><p class="lede">Hosted on Nxeon. Servers with a picture and the ones we run ourselves come first.</p></div></div>`
    + `<div class="dr-grid dr-grid-feat">${f.map((e) => card(e)).join("")}</div></div></section>`;
}

function gameTiles(list: DirEntry[]): string {
  const groups = groupByGame(list);
  if (!groups.length) return "";
  return `<div class="dr-games" role="list">` + groups.map((g) => {
    const art = gameArt(g.game).cover;
    return `<a class="dr-game" role="listitem" href="${esc(nxmHref(`/game-servers/directory/${g.game}`))}">`
      + (art ? `<img src="${esc(art)}" alt="" loading="lazy" width="120" height="160">` : `<span class="dr-game-ph" aria-hidden="true"></span>`)
      + `<span class="dr-game-t"><b>${esc(gameName(g.game))}</b><small>${g.total} server${g.total === 1 ? "" : "s"}${g.nxeon ? ` · ${g.nxeon} on Nxeon` : ""}</small></span></a>`;
  }).join("") + `</div>`;
}

const SEARCH = `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>`;

function tools(list: DirEntry[], chips: { f: string; label: string; n: number }[]): string {
  if (!list.length) return "";
  const c = chips.length > 1
    ? `<div class="dr-chips" role="group" aria-label="Filter"><button type="button" data-f="" aria-pressed="true">All<b>${list.length}</b></button>${chips.map((x) => `<button type="button" data-f="${esc(x.f)}" aria-pressed="false">${esc(x.label)}<b>${x.n}</b></button>`).join("")}</div>`
    : "";
  return `<div class="dr-tools"><label class="dr-search">${SEARCH}<span class="visually-hidden">Search servers</span><input id="dr-q" type="search" placeholder="Search by name, game or address" autocomplete="off"></label>${c}<p class="dr-count" id="dr-count" aria-live="polite">${list.length} server${list.length === 1 ? "" : "s"}</p></div>`;
}

const HOST_CTA = (game?: string) => {
  const route = game ? gameRoute(game) : null;
  return btn(true, route ? staged(route) : nxmHref("/game-servers"), game && route ? `Host your own ${gameName(game)} server` : "Host your own server")
    + `<a class="nxm-glassbtn" href="${esc(nxmHref("/free-minecraft"))}"><span class="nxm-bt">Try a free Minecraft server</span></a>`;
};

const HOW_TO_LIST = [
  ["Run your server on Nxeon", "Order a game server, or create a free Minecraft one. Listing is for servers hosted here."],
  ["Switch on the Public Directory", "Open your server's Settings tab, turn the Public Directory card on and add a short description. Add a picture and link if you like; we review those before they show."],
  ["Players find you here", "A listed server appears with the Nxeon badge while it is running. You can switch it off at any time and it leaves the directory straight away."],
];

const FAQ_COMMON: [string, string][] = [
  ["Do I need an account to join a server?", "No. Copy a server's address and connect from the game. You only need an account to run a server of your own."],
  ["What does the Nxeon badge mean?", "The server is hosted on Nxeon. Entries without it come from public server lists and are shown as found: we do not run them."],
  ["How is the list ordered?", "Servers with a picture first, then servers hosted on Nxeon, then the busiest. Nothing is paid for: nobody can buy a position."],
  ["Why is a server not in the list?", "Only servers whose owner chose to be listed appear, and a server that stops answering drops off. Servers on other lists are included only when they are public and were seen recently."],
  ["Are server addresses safe to share?", "Nxeon-hosted listings show their play address, never a raw IP of ours, and leave the directory the moment the owner switches listing off."],
];

async function homeData() {
  const { entries } = await loadDirectory();
  return entries;
}

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const view = p.view === "all" ? "all" : p.view === "free" ? "free" : p.view === "game" ? "game" : null;
  if (!view) notFound();

  // ── /servers: free Minecraft, unchanged behaviour ────────────────────────
  if (view === "free") {
    const { list, domain } = await freeMinecraftEntries();
    const n = list.length;
    const modes = new Map<string, { label: string; n: number }>();
    list.forEach((e) => modes.set(`mc-${e.region}`, { label: e.region ?? "", n: (modes.get(`mc-${e.region}`)?.n ?? 0) + 1 }));
    const createFree = btn(true, "/dashboard/free-minecraft", "Create my free server");
    const empty = `<div class="au-card dr-empty"><span class="au-tile">${I("server")}</span><h3>No public servers yet</h3><p>Be the first: create a free server and turn on public listing from its Manage tab.</p>${createFree}</div>`;
    const faq: [string, string][] = [
      ["Do I need an account to join a server?", "No. Copy a server's address and connect from Minecraft. You only need an account to run a server of your own."],
      ["How do I list my own server here?", "Create a free Minecraft server, then turn on public listing from its Manage tab. It appears here as soon as it's ready."],
      ["How is the list ordered?", "Newest first. Nothing here is curated or ranked; names, taglines and game modes come from each server's owner."],
      ["Why does a free server take a moment to respond?", "Free servers sleep when nobody is playing. Connecting wakes the server up, and it's back within seconds."],
      ["Are server addresses safe to share?", "Every listing shows a subdomain, never a raw IP address, and a server leaves the directory the moment its owner turns listing off."],
    ];
    return {
      slots: {
        "hero.chip": "Public directory", "hero.h1a": "Public Minecraft servers.", "hero.h1b": "Pick one, connect now.",
        "hero.sub": "Every server below is a real free Nxeon server whose owner opted in to be listed. No account needed to join: copy the address and connect.",
        "hero.ctas:html": createFree + `<a class="nxm-glassbtn" href="${esc(nxmHref("/game-servers"))}"><span class="nxm-bt">Need more power? See paid servers</span></a>`,
        "facts:html": `<li>${I("server")}<b>${n}</b> listed now</li><li>${I("globe")}Addresses on <b>*.${esc(domain)}</b></li><li>${I("users")}No account needed to join</li>`,
        "featured:html": "",
        "list.h": "Browse the directory", "list.lede": "Owner-submitted taglines and game modes. Nothing here is curated or ranked, just newest first.",
        "games:html": "",
        "tools:html": tools(list, [...modes].sort((a, b) => b[1].n - a[1].n).map(([f, g]) => ({ f, label: g.label, n: g.n }))),
        "grid:html": n ? list.map((e) => card(e, { mode: `mc-${e.region}` })).join("") : empty,
        "steps.h": "List your own server here", "steps.lede": "Owners choose to be listed, and can switch it off at any time.",
        "steps:html": [["Create a free server", `No credit card. Pick a name and it's live at yourworld.${domain}.`],
          ["Turn on public listing", "Open your server's Manage tab, switch public listing on and add a tagline."],
          ["Players find you here", "Your server appears in this directory as soon as it's ready, its address one click from copied."]]
          .map(([h, t], i) => `<li class="au-card"><span class="n">0${i + 1}</span><h3>${esc(h)}</h3><p>${esc(t)}</p></li>`).join(""),
        "faq.lede": supportLine(),
        "faq:html": faq.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join(""),
        "final.h": "Get your own free Minecraft server",
        "final.p": "No credit card, live in under a minute, and you can list it here the moment it's ready.",
        "final:html": createFree + `<a class="nxm-glassbtn" href="${esc(nxmHref("/free-minecraft"))}"><span class="nxm-bt">Learn how it works</span></a>`,
      },
      jsonLd: n ? [{
        "@context": "https://schema.org", "@type": "CollectionPage", name: "Public Minecraft server directory", url: `${APP_URL}/servers`,
        mainEntity: { "@type": "ItemList", numberOfItems: n, itemListElement: list.slice(0, 48).map((e, i) => ({ "@type": "ListItem", position: i + 1, name: e.name, url: `${APP_URL}/servers/${e.address.split(".")[0]}` })) },
      }] : [],
      crumb: "Server directory",
    };
  }

  // ── all games / one game ─────────────────────────────────────────────────
  const gameKey = view === "game" ? String(p.game ?? "").toLowerCase() : "";
  if (view === "game" && !isGameFamily(gameKey)) notFound();
  const all = await homeData();
  const list = view === "game" ? all.filter((e) => e.game === gameKey) : all;
  const nx = list.filter((e) => e.nxeon).length;
  const withImg = list.filter((e) => e.imageUrl).length;
  const gamesN = new Set(list.map((e) => e.game)).size;
  const shown = list.slice(0, view === "game" ? CAP_GAME : CAP_HOME);
  const gname = view === "game" ? gameName(gameKey) : "";
  const chips = [
    { f: "nx", label: "Hosted on Nxeon", n: nx },
    { f: "ext", label: "Public lists", n: list.length - nx },
    { f: "img", label: "With picture", n: withImg },
  ].filter((c) => c.n > 0 && c.n < list.length);

  const empty = `<div class="au-card dr-empty"><span class="au-tile">${I("server")}</span><h3>${view === "game" ? `No ${esc(gname)} servers listed yet` : "No servers listed yet"}</h3><p>${view === "game" ? `Be the first to list a ${esc(gname)} server here.` : "Be the first to list your server in the directory."}</p>${HOST_CTA(view === "game" ? gameKey : undefined)}</div>`;

  const facts = `<li>${I("server")}<b>${list.length}</b> listed now</li>`
    + (nx ? `<li>${I("shield")}<b>${nx}</b> hosted on Nxeon</li>` : "")
    + (view === "all" && gamesN > 1 ? `<li>${I("game")}<b>${gamesN}</b> games</li>` : "")
    + `<li>${I("users")}No account needed to join</li>`;

  const faq: [string, string][] = [
    ...FAQ_COMMON,
    ["How do I list my own server here?", "Host it on Nxeon, then switch on the Public Directory card in the game panel's Settings tab and add a short description. Free Minecraft servers have the same switch in their Manage tab. You can also copy a ready-made blurb to submit your server to other public lists."],
  ];

  const route = view === "game" ? `/game-servers/directory/${gameKey}` : "/game-servers/directory";
  const itemList = list.length ? [{
    "@context": "https://schema.org", "@type": "CollectionPage",
    name: view === "game" ? `${gname} server directory` : "Public game server directory", url: APP_URL + route,
    mainEntity: { "@type": "ItemList", numberOfItems: list.length, itemListElement: shown.slice(0, 48).map((e, i) => ({ "@type": "ListItem", position: i + 1, name: e.name })) },
  }] : [];

  return {
    slots: {
      "hero.chip": view === "game" ? `${gname} directory` : "Server directory",
      "hero.h1a": view === "game" ? `${gname} servers` : "Find a server,",
      "hero.h1b": view === "game" ? "to join right now." : "join in one click.",
      "hero.sub": view === "game"
        ? `Public ${gname} servers: the ones hosted on Nxeon and others found on public server lists. Copy an address and connect.`
        : "Community servers across every game, hosted on Nxeon and found on public lists. Pick a game, copy the address, and start playing.",
      "hero.ctas:html": HOST_CTA(view === "game" ? gameKey : undefined),
      "facts:html": facts,
      "featured:html": featuredSection(list),
      "list.h": view === "game" ? `All ${gname} servers` : "Browse by game",
      "list.lede": view === "game"
        ? "Servers with a picture first, then servers hosted on Nxeon, then the busiest."
        : "Pick a game, or search every server below. Servers with a picture come first.",
      "games:html": view === "all" ? gameTiles(list) : "",
      "tools:html": tools(shown, chips),
      "grid:html": shown.length ? shown.map((e) => card(e)).join("") : empty,
      "steps.h": "List your own server here",
      "steps.lede": "Owners choose to be listed, and can switch it off at any time.",
      "steps:html": HOW_TO_LIST.map(([h, t], i) => `<li class="au-card"><span class="n">0${i + 1}</span><h3>${esc(h)}</h3><p>${esc(t)}</p></li>`).join(""),
      "faq.lede": supportLine(),
      "faq:html": faq.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join(""),
      "final.h": view === "game" ? `Host your own ${gname} server` : "Host your own server",
      "final.p": "Get a game server with a control panel, backups and mods, then list it here for others to find.",
      "final:html": HOST_CTA(view === "game" ? gameKey : undefined),
    },
    particles: view === "game" ? undefined : undefined,
    jsonLd: itemList,
    crumb: view === "game" ? gname : "Server directory",
    trail: view === "game" ? [{ name: "Server directory", path: "/game-servers/directory" }] : undefined,
  };
}

export async function meta(p: Record<string, string>) {
  if (p.view === "free") return { image: gameArt("minecraft").hero ?? undefined };
  if (p.view === "all") {
    return {
      title: "Public Game Server Directory",
      description: "Browse public game servers: Minecraft, Valheim, Project Zomboid and more. Servers hosted on Nxeon carry a badge. Pick a game, copy the address and connect.",
      image: gameArt("minecraft").hero ?? undefined,
    };
  }
  if (p.view !== "game") notFound();
  const game = String(p.game ?? "").toLowerCase();
  if (!isGameFamily(game)) notFound();
  const { entries } = await loadDirectory({ game });
  const name = gameName(game);
  return {
    title: `${name} Server List: Public ${name} Servers to Join`,
    description: entries.length
      ? `Public ${name} servers you can join now. ${entries.filter((e) => e.nxeon).length ? "Servers hosted on Nxeon carry a badge. " : ""}Copy an address and connect, or host your own.`
      : `The ${name} server directory. List your own ${name} server hosted on Nxeon for others to find.`,
    image: gameArt(game).hero ?? undefined,
    noindex: !indexableGamePage(entries),
  };
}

