"use server";

/**
 * Owner-side showcase extras for a server's opt-in public listing (mkt-031),
 * plus the ADMIN moderation actions for them. The opt-in itself is still
 * togglePublicListing (lib/actions-game-control.ts); nothing here can make a
 * server public.
 *
 * Moderation model: tagline and description are plain text and show at once.
 * A picture URL and a website URL are customer-supplied https links and are
 * NEVER rendered until an admin approves them; editing either one resets the
 * approval. An admin can hide a listing entirely (`hidden`) or feature it.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { checkRateLimit } from "./rate-limit";
import { cleanText, validHttpsUrl, submissionKit } from "./server-directory";
import { gameSubdomainBase } from "./game-subdomain-dns";

type Result = { ok: true } | { ok: false; error: string };

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true, userId: true, name: true, label: true, subdomain: true, publicListing: true, publicDescription: true,
      gamePlan: { select: { gameFamily: true } }, listingMeta: true,
    },
  });
  if (!s || (s.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  return { user, server: s };
}

const fail = (e: unknown): { ok: false; error: string } =>
  ({ ok: false, error: e instanceof Error && e.message === "Not found" ? "Server not found." : "Could not save. Please try again." });

export type ListingMetaView = {
  tagline: string; imageUrl: string; websiteUrl: string;
  mediaApproved: boolean; hidden: boolean; moderationNote: string | null;
  kit: ReturnType<typeof submissionKit> | null;
};

export async function getListingMeta(serverId: string): Promise<({ ok: true } & ListingMetaView) | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const m = server.listingMeta;
    const base = await gameSubdomainBase();
    const kit = server.subdomain
      ? submissionKit({
        game: server.gamePlan?.gameFamily ?? "minecraft", name: server.label || server.name,
        address: `${server.subdomain}.${base}`, tagline: m?.tagline ?? null, description: server.publicDescription,
      })
      : null;
    return {
      ok: true, tagline: m?.tagline ?? "", imageUrl: m?.imageUrl ?? "", websiteUrl: m?.websiteUrl ?? "",
      mediaApproved: !!m?.mediaApproved, hidden: !!m?.hidden, moderationNote: m?.hidden ? (m.moderationNote ?? null) : null, kit,
    };
  } catch (e) { return fail(e); }
}

export async function saveListingMeta(
  serverId: string,
  input: { tagline: string; imageUrl: string; websiteUrl: string },
): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    const rl = checkRateLimit(`listing:meta:${user.id}`, { max: 20, windowMs: 60_000 });
    if (!rl.ok) return { ok: false, error: `Too many changes — retry in ${rl.retryAfterSec}s.` };
    const tagline = cleanText(input.tagline, 120);
    let imageUrl: string | null = null;
    let websiteUrl: string | null = null;
    if (String(input.imageUrl ?? "").trim()) {
      const v = validHttpsUrl(input.imageUrl);
      if (!v.ok) return { ok: false, error: `Picture: ${v.error}` };
      if (!/\.(png|jpe?g|webp|gif)(\?.*)?$/i.test(new URL(v.url).pathname + new URL(v.url).search)) {
        return { ok: false, error: "Picture: use a direct link to a .png, .jpg, .webp or .gif image." };
      }
      imageUrl = v.url;
    }
    if (String(input.websiteUrl ?? "").trim()) {
      const v = validHttpsUrl(input.websiteUrl);
      if (!v.ok) return { ok: false, error: `Website: ${v.error}` };
      websiteUrl = v.url;
    }
    const prev = server.listingMeta;
    // Changing either link sends it back to review; clearing both leaves nothing to approve.
    const mediaChanged = (prev?.imageUrl ?? null) !== imageUrl || (prev?.websiteUrl ?? null) !== websiteUrl;
    await db.publicListingMeta.upsert({
      where: { serverId },
      create: { serverId, tagline, imageUrl, websiteUrl },
      update: { tagline, imageUrl, websiteUrl, ...(mediaChanged ? { mediaApproved: false } : {}) },
    });
    await recordAudit(user.id, "directory.listing.edit", `server=${serverId} media=${mediaChanged ? "changed" : "same"}`);
    revalidatePath("/game-servers/directory");
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (e) { return fail(e); }
}

