type Row = {
  id: string; slug: string; game: string; name: string; tagline: string | null; status: string; host: string; port: number;
  queryPort: number; region: string | null; maxPlayers: number; passwordPolicy: string; passwordHint: string | null;
  rotation: string | null; wipePolicy: string | null; notes: string | null;
};

export const VALHEIM_DEFAULTS: Row = {
  id: "", slug: "valheim", game: "valheim", name: "Nxeon Community Valheim", tagline: "Free public world. Hop on, build, explore.",
  status: "PLANNED", host: "valheim.nxeon.cloud", port: 2456, queryPort: 2457, region: "bhs1", maxPlayers: 10,
  passwordPolicy: "PUBLISHED", passwordHint: "", rotation: "weekly",
  wipePolicy: "The world is reset if it is griefed beyond repair, and when a major Valheim update breaks old worlds. Daily backups are kept for 7 days.",
  notes: "", 
};

export function FreePublicServerForm({ row, isNew }: { row: Row; isNew?: boolean }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <form
      className="grid gap-3 sm:grid-cols-2"
      action={(fd) => start(async () => { const r = await adminSaveFreePublicServer(fd); setMsg(r.ok ? "Saved." : r.error); })}
    >
      <input type="hidden" name="game" value={row.game} />
      <label className="text-xs text-slate-400">Slug<input className="input mt-1" name="slug" defaultValue={row.slug} readOnly={!isNew} /></label>
      <label className="text-xs text-slate-400">Name<input className="input mt-1" name="name" defaultValue={row.name} /></label>
      <label className="text-xs text-slate-400 sm:col-span-2">Tagline<input className="input mt-1" name="tagline" defaultValue={row.tagline ?? ""} /></label>
      <label className="text-xs text-slate-400">Public host (DNS name)<input className="input mt-1" name="host" defaultValue={row.host} /></label>
      <label className="text-xs text-slate-400">Region code<input className="input mt-1" name="region" defaultValue={row.region ?? ""} /></label>
      <label className="text-xs text-slate-400">Game port (UDP)<input className="input mt-1" name="port" type="number" defaultValue={row.port} /></label>
      <label className="text-xs text-slate-400">Query port (UDP, Valheim = game+1)<input className="input mt-1" name="queryPort" type="number" defaultValue={row.queryPort} /></label>
      <label className="text-xs text-slate-400">Max players<input className="input mt-1" name="maxPlayers" type="number" defaultValue={row.maxPlayers} /></label>
      <label className="text-xs text-slate-400">Status
        <select className="input mt-1" name="status" defaultValue={row.status}>
          {["PLANNED", "LIVE", "MAINTENANCE", "RETIRED"].map((s) => <option key={s}>{s}</option>)}
        </select>
      </label>
      <label className="text-xs text-slate-400">Password policy
        <select className="input mt-1" name="passwordPolicy" defaultValue={row.passwordPolicy}>
          <option value="PUBLISHED">PUBLISHED (rotating, shown on the page)</option>
          <option value="OPEN">OPEN (no password)</option>
        </select>
      </label>
      <label className="text-xs text-slate-400">Current published password<input className="input mt-1 font-mono" name="passwordHint" defaultValue={row.passwordHint ?? ""} autoComplete="off" /></label>
      <label className="text-xs text-slate-400">Rotation cadence (text)<input className="input mt-1" name="rotation" defaultValue={row.rotation ?? ""} /></label>
      <label className="text-xs text-slate-400 sm:col-span-2">Wipe / reset policy (shown to players)<textarea className="input mt-1" rows={2} name="wipePolicy" defaultValue={row.wipePolicy ?? ""} /></label>
      <label className="text-xs text-slate-400 sm:col-span-2">Internal notes (never shown)<textarea className="input mt-1" rows={2} name="notes" defaultValue={row.notes ?? ""} /></label>
      <div className="flex items-center gap-3 sm:col-span-2">
        <button className="btn-primary" disabled={pending}>{pending ? "Saving…" : isNew ? "Create" : "Save"}</button>
        {msg && <span className="text-xs text-slate-300">{msg}</span>}
      </div>
    </form>
  );
}

export function FreePublicRowActions({ id, status, policy }: { id: string; status: string; policy: string }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const [pw, setPw] = useState("");
  const flip = (s: string) => start(async () => { const r = await adminSetFreePublicStatus(id, s); setMsg(r.ok ? `Now ${s}.` : r.error); });
  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-2">
        <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => start(async () => {
          const r = await adminProbeFreePublicServer(id);
          if (!r.ok) return setMsg(r.error);
          setMsg(r.live.state === "online"
            ? `Online: ${r.live.players}/${r.live.max ?? "?"} players${r.live.version ? ` · game ${r.live.version}` : ""}${r.playerListCount != null ? ` · player list has ${r.playerListCount}` : ""}`
            : "No A2S answer (server down, query port not forwarded, or firewalled).");
        })}>Probe now</button>
        {status !== "LIVE" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => confirm("Make this server visible to the public (directory + marketing page)?") && flip("LIVE")}>Go LIVE</button>}
        {status === "LIVE" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => flip("MAINTENANCE")}>Maintenance</button>}
        {status !== "RETIRED" && <button className="btn-ghost py-1 text-xs text-red-300" disabled={pending} onClick={() => confirm("Retire this server? It disappears from every public page.") && flip("RETIRED")}>Retire</button>}
      </div>
      {policy === "PUBLISHED" && (
        <div className="flex items-center gap-2">
          <input className="input w-48 py-1 font-mono text-xs" placeholder="new password after rotation" value={pw} onChange={(e) => setPw(e.target.value)} autoComplete="off" />
          <button className="btn-ghost py-1 text-xs" disabled={pending || !pw} onClick={() => start(async () => { const r = await adminSetFreePublicPassword(id, pw); setMsg(r.ok ? "Published password updated." : r.error); if (r.ok) setPw(""); })}>Publish password</button>
        </div>
      )}
      {msg && <p className="text-xs text-slate-300">{msg}</p>}
    </div>
  );
}

