cd /opt/nxeon-wt-g6; cat > test/server-directory.test.ts <<'E'
import test from "node:test";
import assert from "node:assert/strict";
import {
  connKey, parseConnection, normalizeHost, dedupeEntries, rankEntries, pickFeatured, groupByGame,
  indexableGamePage, validHttpsUrl, cleanText, submissionKit, type DirEntry,
} from "../lib/server-directory";
import { parseValveResponse, parseValveRow, cleanServerName } from "../lib/directory-ingest/valve";
import { splitDuplicates } from "../lib/directory-ingest/run";

const base = (o: Partial<DirEntry>): DirEntry => ({
  key: "k", source: "external", nxeon: false, game: "valheim", name: "Srv", tagline: "", description: "", imageUrl: null,
  address: "1.2.3.4:2456", host: "1.2.3.4", port: 2456, alsoKeys: [], players: null, maxPlayers: null, country: null,
  region: null, featured: false, href: null, websiteUrl: null, seenAt: null, ...o,
});

test("connKey: host, host:default and uppercase/trailing-dot forms are one connection", () => {
  assert.equal(connKey("minecraft", "PLAY.Example.com.", null), "play.example.com:25565");
  assert.equal(connKey("minecraft", "play.example.com", 25565), connKey("minecraft", "play.example.com", null));
  assert.equal(connKey("minecraft", "001.002.003.004", null), "1.2.3.4:25565");
  assert.notEqual(connKey("valheim", "1.2.3.4", 2456), connKey("valheim", "1.2.3.4", 2466));
});

test("parseConnection: scheme/path stripped, junk rejected", () => {
  assert.deepEqual(parseConnection("play.example.com:25566"), { host: "play.example.com", port: 25566 });
  assert.deepEqual(parseConnection("https://play.example.com/join"), { host: "play.example.com", port: null });
  assert.deepEqual(parseConnection("1.2.3.4"), { host: "1.2.3.4", port: null });
  assert.equal(parseConnection("not a host"), null);
  assert.equal(parseConnection("host:99999"), null);
  assert.equal(parseConnection("localhost"), null);
});

test("dedupe: same domain / same ip:port collapse; different ports on one ip do not", () => {
  const a = base({ key: "a", host: "play.x.com", port: null, address: "play.x.com", game: "minecraft", name: "A" });
  const b = base({ key: "b", host: "PLAY.x.com", port: 25565, address: "PLAY.x.com:25565", game: "minecraft", name: "B" });
  const c = base({ key: "c", host: "9.9.9.9", port: 2456, address: "9.9.9.9:2456", name: "C" });
  const d = base({ key: "d", host: "9.9.9.9", port: 2466, address: "9.9.9.9:2466", name: "D" });
  const r = dedupeEntries([a, b, c, d]);
  assert.equal(r.entries.length, 3);
  assert.equal(r.dropped, 1);
  assert.deepEqual(r.entries.map((e) => e.key).sort(), ["a", "c", "d"].sort().map((k) => (k === "a" ? r.entries.find((e) => e.host.toLowerCase() === "play.x.com")!.key : k)));
});

test("dedupe: an Nxeon entry swallows an external row that has its node ip:port, and is never edited by it", () => {
  const ours = base({ key: "n", source: "nxeon-paid", nxeon: true, host: "mine.play.nxeon.cloud", port: null, address: "mine.play.nxeon.cloud", alsoKeys: ["51.0.0.1:20456"], description: "Ours" });
  const theirs = base({ key: "x", host: "51.0.0.1", port: 20456, address: "51.0.0.1:20456", imageUrl: "https://i.example/x.png", description: "Theirs", players: 9 });
  const r = dedupeEntries([theirs, ours]);
  assert.equal(r.entries.length, 1);
  assert.equal(r.entries[0].key, "n");
  assert.equal(r.entries[0].imageUrl, null, "third-party data never rewrites an Nxeon listing");
  assert.equal(r.entries[0].description, "Ours");
});

test("dedupe: external duplicates keep the one with an image and inherit what the others know", () => {
  const withImg = base({ key: "i", imageUrl: "https://i.example/a.png", host: "5.5.5.5", port: 2456, address: "5.5.5.5:2456" });
  const withDesc = base({ key: "d", description: "A long friendly description of the server", host: "5.5.5.5", port: 2456, address: "5.5.5.5:2456", country: "SG" });
  const r = dedupeEntries([withDesc, withImg]);
  assert.equal(r.entries.length, 1);
  assert.equal(r.entries[0].key, "i");
  assert.equal(r.entries[0].description, "A long friendly description of the server");
  assert.equal(r.entries[0].country, "SG");
});

test("dedupe is transitive and order-independent", () => {
  const a = base({ key: "a", host: "a.example.com", port: 2456, alsoKeys: ["7.7.7.7:2456"], name: "a" });
  const b = base({ key: "b", host: "7.7.7.7", port: 2456, alsoKeys: ["8.8.8.8:2456"], name: "b" });
  const c = base({ key: "c", host: "8.8.8.8", port: 2456, name: "c", imageUrl: "https://i.example/c.png" });
  for (const order of [[a, b, c], [c, b, a], [b, c, a]]) {
    const r = dedupeEntries(order);
    assert.equal(r.entries.length, 1);
    assert.equal(r.entries[0].key, "c");
  }
});

test("rank: image first, then Nxeon, then busiest", () => {
  const list = [
    base({ key: "1", name: "plain", players: 50 }),
    base({ key: "2", name: "nx", nxeon: true, source: "nxeon-paid", players: 1 }),
    base({ key: "3", name: "img", imageUrl: "https://i.example/a.png", players: 0 }),
    base({ key: "4", name: "imgnx", nxeon: true, source: "nxeon-paid", imageUrl: "https://i.example/b.png" }),
  ];
  assert.deepEqual(rankEntries(list).map((e) => e.key), ["4", "3", "2", "1"]);
});

test("featured: only Nxeon-hosted entries (featured, community, or with a picture)", () => {
  const list = [
    base({ key: "e", name: "ext img", imageUrl: "https://i.example/a.png" }),
    base({ key: "p", name: "plain nx", nxeon: true, source: "nxeon-paid" }),
    base({ key: "f", name: "feat", nxeon: true, source: "nxeon-paid", featured: true }),
    base({ key: "c", name: "comm", nxeon: true, source: "nxeon-community" }),
  ];
  assert.deepEqual(pickFeatured(list).map((e) => e.key).sort(), ["c", "f"]);
});

test("groupByGame counts per game", () => {
  const g = groupByGame([base({ game: "valheim", nxeon: true }), base({ game: "valheim", key: "2", host: "2.2.2.2" }), base({ game: "rust", key: "3", host: "3.3.3.3" })]);
  assert.equal(g[0].game, "valheim");
  assert.equal(g[0].total, 2);
  assert.equal(g[0].nxeon, 1);
});

test("indexable only with enough described, recently seen servers", () => {
  const now = Date.now();
  const d = (i: number, seen: number | null) => base({ key: String(i), description: "A real description here", seenAt: seen });
  assert.equal(indexableGamePage([d(1, now), d(2, now)], now), false);
  assert.equal(indexableGamePage([d(1, now), d(2, now), d(3, null)], now), true);
  assert.equal(indexableGamePage([d(1, now), d(2, now), d(3, now - 30 * 86_400_000)], now), false);
