/**
 * Shared prop shapes for the premium game-server management panel
 * (components/customer/gamepanel/*). Kept in a plain module so the client shell,
 * header and tabs can all import the same types without pulling server code.
 */
import type { PowerSnapshot } from "@/lib/power-state";
import type { RuntimeView } from "@/lib/game-runtime";

export type HeaderStat = {
  /** current value, already scaled to its display unit */
  value: number;
  /** the ceiling for the meter (same unit as `value`) */
  max: number;
};

export type GameHeaderData = {
  /** customer-facing server name (label || name) */
  name: string;
  /** pretty game name, e.g. "Rust", "Minecraft" */
  gameLabel: string;
  /** raw ServerStatus (RUNNING, STOPPED, …) — the VM's power state */
  status: string;
  /**
   * The GAME is (believed) up — from the runtime probe, NOT the VM status
   * (lib/game-runtime.ts). Drives player/metrics polling.
   */
  running: boolean;
  /** the VM itself is running (SSH-backed panels like logs work) */
  vmRunning?: boolean;
  /**
   * The game's runtime truth (badge, detail, which power controls apply), or
   * null when the VM is not running — the VM status is then the whole story.
   */
  runtime?: RuntimeView | null;
  /** literal ip:port for clients that can't resolve the Minecraft SRV subdomain */
  directConnect?: string | null;
  /** ip:port players connect to, or null while provisioning */
  connect: string | null;
  /** short server id badge, e.g. "#srv_8f7a2c1d" */
  serverIdShort: string;
  node: string | null;
  location: string | null;
  /** ISO-3166 alpha-2 for the location flag, or null when unknown. */
  locationCountry?: string | null;
  players: { online: number; max: number | null };
  /** CPU percent 0-100 */
  cpuPct: number;
  /**
   * memory in bytes. usedBytes is NOT Proxmox's live `mem` balloon field —
   * that stat is MemFree-based, not MemAvailable-based, so a server with
   * ordinary disk/page-cache activity (the game's own world/save files count)
   * reads falsely high "memory used" even with plenty of genuinely spare
   * RAM. usedBytes comes from ServerMemSample (the worker's periodic
   * guest-agent /proc/meminfo read) instead, and is null until a sample has
   * landed — maxBytes is always known (provisioned RAM) so it stays plain.
   */
  mem: { usedBytes: number | null; maxBytes: number };
  /** disk in GB */
  disk: { usedGB: number; maxGB: number };
  /** network throughput, MB/s (null when unknown) */
  net: { inMbps: number | null; outMbps: number | null };
  uptimeLabel: string;
  createdLabel: string;
  nextRestartLabel: string | null;
  /** power controls are usable (VM steady + not busy) */
  canControl: boolean;
  /**
   * The server's real GAME_POWER job state (lib/power-state.ts): what is in
   * flight, how the last one ended, or which other job is holding the controls.
   */
  power: PowerSnapshot;
  /** customer's own domain pointing at this server (null = none set) */
  customDomain: string | null;
  /** whether the custom domain's DNS has been verified */
  customDomainVerified: boolean;
};

export type PanelTab =
  | "overview"
  | "console"

if (isGameServer) {
  const gameFamilyKey = server.gamePlan?.gameFamily ?? server.osTemplate.family;
  /* The GAME's name, not the OS image's. `gameLabel` read `osTemplate.name`,
     so a Minecraft server installed on a plain Ubuntu image introduced itself
     as "Ubuntu 24.04 LTS" everywhere the panel names the game — including the
     Build-with-AI prompts, which offered to tune "your Ubuntu 24.04 LTS
     server for competitive PvP". Same wrong-column bug as isGameServer. */
  const gameDisplayName =
    GAME_DISPLAY[gameFamilyKey as keyof typeof GAME_DISPLAY]?.name ?? server.osTemplate.name;
  const gameLabel = gameDisplayName;
  const gameForward = gameForwardFor(server);
  const connectPort = server.dedicatedIp ? gameForward?.guestPort : gameForward?.publicPort;
  const rawConnect = server.dedicatedIp
    ? `${server.dedicatedIp.address}${gameForward ? `:${gameForward.guestPort}` : ""}`
    : gameForward
      ? `${publicIp}:${gameForward.publicPort}`
      : publicIp || null;
  // A Java Minecraft subdomain (SRV-backed, see lib/game-subdomain-dns.ts)
  // needs no port shown at all — the client resolves it automatically. Every
  // other family with a subdomain (Bedrock + HOSTNAME_CONNECT_FAMILIES,
  // lib/games.ts) has NO SRV support, so the port must still be appended —
  // showing a bare hostname there would reproduce the exact "no port needed"
  // miscopy already found and fixed for Bedrock's checkout wizard.
  const gameSubdomainDomain = await gameSubdomainBase();
  const connect = server.subdomain
    ? gameFamilyKey === "minecraft"
      ? `${server.subdomain}.${gameSubdomainDomain}`
      : `${server.subdomain}.${gameSubdomainDomain}${connectPort ? `:${connectPort}` : ""}`
    : rawConnect;

  // Effective public IP + port for the custom-domain DNS instructions.
  const effectiveIp = server.dedicatedIp?.address ?? publicIp;
  const effectivePort = server.dedicatedIp
    ? (gameForward?.guestPort ?? 25565)
    : (gameForward?.publicPort ?? 25565);

  // Soonest enabled auto-restart, for the "Next restart" field.
  const nextSchedule = await db.gameSchedule.findFirst({
    where: { serverId: server.id, enabled: true, nextRunAt: { not: null } },
    orderBy: { nextRunAt: "asc" },
  });

  const latestDisk = await db.serverDiskSample.findFirst({
    where: { serverId: server.id },
    orderBy: { ts: "desc" },
    select: { usedBytes: true },
  }).catch(() => null);
  const diskUsedGB = latestDisk ? Number(latestDisk.usedBytes) / (1024 ** 3) : 0;

  // `Server.status` is the VM's own power state; the GAME inside it is a
  // different thing, and the badge + power controls must follow the game.
  // INCIDENT 2026-09-30 (tomatikk, docs/DOCUMENTATION.md): the game was
  // stopped, this page derived "Online" from `server.status === "RUNNING"`,
  // the Start button was disabled, and the customer could not start their
  // own server. `runtimeView` (lib/game-runtime.ts) reads the cached
  // in-guest probe + the recorded run intent instead; with no fresh probe it
  // says "Checking…" and leaves every control available — never "Online"
  // on a guess. The probe itself is refreshed after render by
  // GameRuntimeRefresher, so this read is a single cheap DB row.
  const runtime = runtimeView({
    vmStatus: server.status,
    row: server.gameRuntime,
    now: new Date(),
    legacyServiceState: (server.gameConfig as Record<string, unknown> | null)?._serviceState,
  });
  const displayStatus = server.status;
  return (
    <div>
      {overlay}
      {busy && <AutoRefresh />}

      {server.status === "SUSPENDED" && (
        <div className="card mb-6 border-red-500/30 text-sm text-red-300">
          This server has been suspended{server.suspendedNote ? `: ${server.suspendedNote}` : "."}{" "}
          Contact support if you believe this is a mistake.
        </div>
      )}
      {server.status === "ERROR" && <ProvisionErrorBanner serverId={server.id} reason={server.provisionError} />}
      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          {server.status === "DELETING"
            ? "Your server is being deleted…"
            : "Your server is being set up — this usually takes under two minutes. The page refreshes automatically."}
        </div>
      )}

      <div className="mb-3 flex items-center justify-between gap-3">
        <a href="/dashboard/services" className="text-[12.5px] text-tx-faint transition hover:text-white">
          ← My Services
        </a>
        <ServerTour server={server} isGame />
      </div>

      <GamePanelShell
        serverId={server.id}
        gameFamily={gameFamilyKey}
        header={header}
        /* The facts the hero does NOT already show, so Overview stops
           repeating identity back at the reader one card below it. */
        facts={{
          planName: server.gamePlan?.name ?? server.plan.name,
          planSpec: server.gamePlan
            ? `${server.gamePlan.cpuCores} vCPU · ${Math.round(server.gamePlan.ramMB / 1024)} GB RAM · ${server.gamePlan.slots} slots`
            : `${server.plan.cpuCores} vCPU · ${Math.round(server.plan.ramMB / 1024)} GB RAM`,
          createdLabel: server.createdAt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
          node: server.node?.name ?? null,
          serverIdShort: `#${server.id.slice(0, 10)}`,
          renewalLabel: server.expiresAt
            ? server.expiresAt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })
            : null,
          autoRenew: server.autoRenew,
          variantLabel: server.gameVariant ?? null,
          planTotalGB: totalDiskGB,
        }}
        filesPanel={gameFilesPanel}
        backupsPanel={gameBackupsTab}
        settingsPanel={gameSettingsPanel}
        activityPanel={gameActivity}
        initialTab={tab}
      />
    </div>
  );
}


return (
  <div className="flex flex-col gap-4">
    {overlay}
    {busy && <AutoRefresh />}

    {/* Identity, status, address and power all live in the hero now. The
        page-level header this replaces restated the plan, the OS and the
        hostname that the hero carries, and mounted a SECOND terminal button
        beside controls the hero already owns. */}
    <div className="mx-auto -mb-2 flex w-full max-w-[1480px] justify-end">
      <ServerTour server={server} isGame={false} />
    </div>
    <VpsPanelShell
      data={vpsHeader}
      busy={busy}
      suspendReason={server.suspendedNote ?? server.suspendReason ?? null}
      provisionError={server.provisionError ?? null}
      initialTab={tab}
      overviewPanel={overview}
      consolePanel={consolePanel}
      filesPanel={filesPanel}
      servicesPanel={<VpsServicesPanel serverId={server.id} running={server.status === "RUNNING"} />}
      backupsPanel={backupsTab}
      snapshotsPanel={snapshotsTab}
      networkingPanel={networking}
      settingsPanel={vpsSettingsPanel}
      activityPanel={activity}
}


// Per-game customization (only for game servers with a customization schema).
const gameFamily = familyFor(server);
const gameSchema = schemaFor(gameFamily);
const gameVariant =
  gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
    ? server.gameVariant
    : gameSchema?.defaultVariant ?? "";
const gameValidated = gameFamily
  ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
  : null;
const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};

/* ---------- Tab: Overview ---------- */
/* ---------- The panel's identity + vitals snapshot ----------
   Assembled once and handed to the shell. The address comes from
   lib/nx/connect-address.ts rather than being worked out again — this page
   had re-derived the same answer inline in four separate places. */
const vpsUptime = await uptimeFor([server.id]);

