/**
 * "How do my PS5 / Xbox friends join?" — generated per server (growth item
 * prd-015). PURE: a function of the family, the saved game settings and the
 * server's connect address, so the panel card and the join kit (prd-012) can
 * share it and it is unit-tested.
 *
 * Grounded in what this repo already knows from real tickets and the images'
 * own docs (lib/game-config.ts, worker/game-config.ts):
 *  - Palworld: console builds have no way to type an IP. A console player's only
 *    route is the in-game Community Servers browser, searching by the exact
 *    Server Name, and the server must be listed there (COMMUNITY=true). PC players
 *    use the address. (ticket 13, 2026-09-30)
 *  - Valheim: Xbox/PlayStation clients can only join a server run with crossplay
 *    on (CROSSPLAY=true on the lloesche image). Consoles find it by name or use the join
 *    code the server prints in its log. (ticket 6, 2026-09-15)
 * Families not listed return null: no console-join card is shown rather than
 * guessing steps for a game we have not verified.
 */

export type ConsoleJoin = {
  family: "palworld" | "valheim";
  platforms: string[];
  /** ready: console players can join now. action: a setting must change first. */
  status: "ready" | "action";
  headline: string;
  /** The exact name console players search for (null when unknown). */
  serverName: string | null;
  steps: string[];
  notes: string[];
  /** Present when status is "action": what to change and where. */
  fix: { label: string; where: string } | null;
  /** Valheim only: the card can look the join code up in the server log. */
  joinCodeFromLog: boolean;
};

type Values = Record<string, string | number | boolean | undefined>;

const truthy = (v: unknown) => v === true || String(v ?? "").toLowerCase() === "true" || v === 1 || v === "1";
const str = (v: unknown, fallback: string) => (typeof v === "string" && v.trim() ? v.trim() : fallback);

export const PALWORLD_DEFAULT_NAME = "Nxeon Palworld Server";
export const VALHEIM_DEFAULT_NAME = "Nxeon";

export function consoleJoinInfo(i: { family: string | null | undefined; values: Values; connect: string | null }): ConsoleJoin | null {
  if (i.family === "palworld") {
    const name = str(i.values["server-name"], PALWORLD_DEFAULT_NAME);
    // The schema default is ON; only an explicit false hides the server.
    const listed = i.values["community-servers"] === undefined ? true : truthy(i.values["community-servers"]);
    return {
      family: "palworld", platforms: ["PlayStation 5", "Xbox"],
      status: listed ? "ready" : "action",
      headline: listed
        ? "PlayStation 5 and Xbox players join by searching for the server's name."
        : "Console players cannot find this server yet: it is not listed in the in-game browser.",
      serverName: name,
      steps: [
        "On PS5 or Xbox, start Palworld and choose Join Multiplayer Game.",
        "Open the Community Servers list. Consoles cannot type an IP address, so this list is the only way in.",
        `Search for the exact server name: ${name}`,
        "Select the server and enter its password if you set one.",
      ],
      notes: [
        i.connect ? `PC players can skip all of this and join by address: ${i.connect}` : "PC players can join by the server address.",
        "After a restart the server can take a few minutes to show up in the list. If it is missing, wait and search again.",
        name === PALWORLD_DEFAULT_NAME ? "Tip: the name is still the default. A more distinctive name is easier to find among hundreds of servers." : "Spelling and capitals matter: share the name exactly as shown.",
      ],
      fix: listed ? null : { label: "Turn on “List in the in-game Community Servers browser”", where: "Settings tab, Access section" },
      joinCodeFromLog: false,
    };
  }
  if (i.family === "valheim") {
    const name = str(i.values["SERVER_NAME"], VALHEIM_DEFAULT_NAME);
    const on = truthy(i.values["CROSSPLAY"]);
    return {
      family: "valheim", platforms: ["PlayStation 5", "Xbox", "Game Pass PC"],
      status: on ? "ready" : "action",
      headline: on
        ? "Crossplay is on: console players can join by name or with the server's join code."
        : "Console players cannot join yet: Crossplay is switched off for this server.",
      serverName: name,
      steps: [
        "On PS5 or Xbox, start Valheim, choose Start Game, then pick or create your character.",
        "Choose Join Game.",
        `Find the server in the Community list by its exact name: ${name}`,
        "Or choose Join with code and enter the join code (the button below finds it for you).",
        "Enter the server password when asked.",
      ],
      notes: [
        i.connect ? `Steam players can join by address as usual: ${i.connect}` : "Steam players can join by the server address.",
        "Everyone needs the same Valheim version as the server. If the game says the version does not match, update it and try again.",
        "Turning Crossplay on or off restarts the server briefly.",
      ],
      fix: on ? null : { label: "Turn on “Crossplay”", where: "Settings tab, General section" },
      joinCodeFromLog: on,
    };
  }
  return null;
}

/** Valheim prints `... join code 123456 ...` when a crossplay server registers. Null when absent. */
export function parseValheimJoinCode(lines: string[]): string | null {
  for (let n = lines.length - 1; n >= 0; n--) {
    const m = /join code\s+(\d[\d ]{2,10}\d)\b/i.exec(lines[n]);
    if (m) return m[1].replace(/\s+/g, "");
  }
  return null;
}

/** Plain text of the instructions, for the copy button and the join kit. */
export function consoleJoinText(c: ConsoleJoin): string {
  return [
    `How to join from ${c.platforms.join(" / ")}`,
    ...c.steps.map((s, k) => `${k + 1}. ${s}`),
    "",
    ...c.notes,
  ].join("\n");
}
