cat > test/console-join.test.ts <<'E'
import test from "node:test";
import assert from "node:assert/strict";
import { consoleJoinInfo, parseValheimJoinCode, consoleJoinText, PALWORLD_DEFAULT_NAME } from "../lib/console-join";

test("palworld: listed by default, searches by the exact configured name", () => {
  const c = consoleJoinInfo({ family: "palworld", values: { "server-name": "Moa's Island" }, connect: "1.2.3.4:8211" })!;
  assert.equal(c.status, "ready");
  assert.equal(c.serverName, "Moa's Island");
  assert.ok(c.steps.some((s) => s.includes("Moa's Island")));
  assert.ok(c.notes.some((n) => n.includes("1.2.3.4:8211")));
  assert.equal(c.fix, null);
});

test("palworld: default name and unlisted server are called out", () => {
  const d = consoleJoinInfo({ family: "palworld", values: {}, connect: null })!;
  assert.equal(d.serverName, PALWORLD_DEFAULT_NAME);
  assert.equal(d.status, "ready");
  assert.ok(d.notes.some((n) => /default/i.test(n)));
  const off = consoleJoinInfo({ family: "palworld", values: { "community-servers": false }, connect: null })!;
  assert.equal(off.status, "action");
  assert.match(off.fix!.label, /Community Servers/);
  assert.equal(consoleJoinInfo({ family: "palworld", values: { "community-servers": "false" }, connect: null })!.status, "action");
});

test("valheim: crossplay gates console join", () => {
  const off = consoleJoinInfo({ family: "valheim", values: { CROSSPLAY: false, SERVER_NAME: "Hall" }, connect: null })!;
  assert.equal(off.status, "action");
  assert.equal(off.joinCodeFromLog, false);
  assert.match(off.fix!.label, /Crossplay/);
  const on = consoleJoinInfo({ family: "valheim", values: { CROSSPLAY: true, SERVER_NAME: "Hall" }, connect: "x:2456" })!;
  assert.equal(on.status, "ready");
  assert.equal(on.joinCodeFromLog, true);
  assert.equal(on.serverName, "Hall");
});

test("other games: no card (no guessing)", () => {
  for (const f of ["ark", "rust", "minecraft", null, undefined]) assert.equal(consoleJoinInfo({ family: f, values: {}, connect: null }), null);
});

test("join code is read from the newest matching log line only", () => {
  const lines = [
    'Session "Hall" with join code 123456 and IP 1.2.3.4:2456 is active with 0 player(s)',
    "noise",
    'Session "Hall" with join code 654 321 and IP 1.2.3.4:2456 is active with 2 player(s)',
  ];
  assert.equal(parseValheimJoinCode(lines), "654321");
  assert.equal(parseValheimJoinCode(["nothing here"]), null);
});

test("text export contains every step", () => {
  const c = consoleJoinInfo({ family: "palworld", values: {}, connect: null })!;
  const t = consoleJoinText(c);
  c.steps.forEach((s) => assert.ok(t.includes(s)));
});
