"use client";

import { useCallback, useEffect, useState } from "react";
import { getPlayerHistory, type PlayerSessionRow } from "@/lib/actions-game-control";

/**
 * Body of the "Recent joins" card (growth item prd-014): who joined and when,
 * newest first, from the server's own real PlayerSession rows (RCON polling for
 * Minecraft; log tailing for Valheim and Rust — worker/game-control.ts). A
 * player who joined before tracking started is not listed (the first sweep
 * seeds silently), and a "left" time marked ~ is inferred from the headcount,
 * not observed — the footnote says so rather than presenting a guess as fact.
 */
const when = (iso: string) => {
  const d = Date.now() - new Date(iso).getTime();
  if (d < 60_000) return "just now";
  const m = Math.floor(d / 60_000);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 48) return `${h}h ago`;
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" });
};
const full = (iso: string) => new Date(iso).toLocaleString("en-US", { dateStyle: "medium", timeStyle: "short" });

export function GameJoinLog({ serverId, limit = 10, onNavigate }: { serverId: string; limit?: number; onNavigate?: (tab: string) => void }) {
  const [rows, setRows] = useState<PlayerSessionRow[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const load = useCallback(async () => {
    const r = await getPlayerHistory(serverId, { limit }).catch(() => null);
    if (!r) return;
    if (r.ok) { setRows(r.sessions); setErr(null); } else setErr(r.error);
  }, [serverId, limit]);
  useEffect(() => {
    void load();
    const t = setInterval(load, 60_000);
    return () => clearInterval(t);
  }, [load]);

  if (err) return <p className="text-[12.5px] text-amber-300">{err}</p>;
  if (!rows) return <p className="text-[12.5px] text-tx-faint">Loading…</p>;
  if (rows.length === 0) {
    return <p className="text-[12.5px] leading-relaxed text-tx-faint">No joins recorded yet. Each time someone connects it appears here with the time. Joins from before tracking started are not back-filled.</p>;
  }
  return (
    <div className="flex flex-col gap-2">
      <ul className="flex flex-col gap-1.5">
        {rows.map((s) => (
          <li key={s.id} className="flex items-center gap-2.5 rounded-[10px] border border-rim-soft bg-well px-3 py-2">
            <span className="grid h-[26px] w-[26px] flex-none place-items-center rounded-[8px] bg-[linear-gradient(140deg,#2f6fe0,#7b3fef)] text-[10.5px] font-bold text-white">{s.playerName.slice(0, 2).toUpperCase()}</span>
            <span className="min-w-0 flex-1">
              <span className="block truncate text-[12.5px] font-semibold text-white">{s.playerName}</span>
              <span className="block truncate text-[11px] text-tx-faint" title={full(s.joinedAt)}>
                Joined {when(s.joinedAt)}{s.leftAt ? ` · left ${s.leftAtInferred ? "~" : ""}${when(s.leftAt)}` : ""}
              </span>
            </span>
            {!s.leftAt && <span className="flex-none text-[11px] font-semibold text-emerald-400">Online</span>}
          </li>
        ))}
      </ul>
      <p className="text-[11px] leading-relaxed text-tx-faint">
        Names come from the game&apos;s own log. A time marked ~ is an estimate.
        {onNavigate && <> <button type="button" onClick={() => onNavigate("players")} className="font-semibold text-brand-300 hover:text-white">Full history →</button></>}
      </p>
    </div>
  );
}
