export const RCON_TRACKED_FAMILIES = ["minecraft", "cs2", "palworld", "ark", "projectzomboid", "arkasa", "tf2", "l4d2"] as const;
export const LOG_TRACKED_FAMILIES = ["valheim", "rust"] as const;

