"use server";

/**
 * Region-transfer REQUESTS (growth item prd-016). Creating a request moves
 * nothing: it records the customer's ask and their acknowledgement of the
 * downtime, for an admin to review in /admin/transfer-requests. The VM move
 * engine itself is not exposed to customers (NO-GO until rehearsals are done).
 * Gated by Setting region_transfer_enabled (default off) on EVERY action, so
 * flipping the flag off also stops requests already in flight from being made.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { checkRateLimit } from "./rate-limit";
import { getSettingBool } from "./settings";
import { customerRegionLabel } from "./node-regions";
import {
  OPEN_STATUSES, estimateDowntime, targetRegions, ineligibleReason, cleanNote, type TargetRegion, type Estimate,
} from "./region-transfer";

type Result = { ok: true } | { ok: false; error: string };

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true, userId: true, status: true, isFree: true, name: true, label: true, gamePlanId: true,
      dedicatedIp: { select: { id: true } },
      node: { select: { region: true } },
    },
  });
  if (!s || (s.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  return { user, server: s };
}

async function usedGb(serverId: string): Promise<number | null> {
  const d = await db.serverDiskSample.findFirst({ where: { serverId }, orderBy: { ts: "desc" }, select: { usedBytes: true } }).catch(() => null);
  return d ? Number(d.usedBytes) / 1024 ** 3 : null;
}

export type TransferView = {
  enabled: boolean;
  blocked: string | null;
  fromLabel: string | null;
  targets: TargetRegion[];
  estimate: Estimate;
  sizeGb: number | null;
  open: { id: string; status: string; toLabel: string; createdAt: string } | null;
  recent: { id: string; status: string; toLabel: string; createdAt: string; adminNote: string | null }[];
};

export async function getTransferView(serverId: string): Promise<({ ok: true } & TransferView) | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const flagOn = await getSettingBool("region_transfer_enabled", false);
    const [reqs, nodes, size] = await Promise.all([
      db.regionTransferRequest.findMany({ where: { serverId }, orderBy: { createdAt: "desc" }, take: 5 }).catch(() => []),
      db.node.findMany({ select: { region: true, enabled: true, status: true, acceptsProvisions: true } }),
      usedGb(serverId),
