"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  getTransferView, requestRegionTransfer, cancelRegionTransfer, type TransferView,
} from "@/lib/actions-region-transfer";

/**
 * "Move to another location" card (growth item prd-016). It only ever creates a
 * REQUEST that Nxeon staff review; nothing is moved from here. Hidden entirely
 * while Setting region_transfer_enabled is off (getTransferView says so).
 */
const STATUS_TEXT: Record<string, string> = {
  REQUESTED: "Waiting for review",
  APPROVED: "Approved: we will contact you to agree a time",
  REJECTED: "Declined",
  COMPLETED: "Completed",
  CANCELLED: "Cancelled",
};

export function GameRegionTransfer({ serverId }: { serverId: string }) {
  const [v, setV] = useState<(Extract<Awaited<ReturnType<typeof getTransferView>>, { ok: true }>) | null>(null);
  const [to, setTo] = useState("");
  const [note, setNote] = useState("");
  const [ack, setAck] = useState(false);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pending, start] = useTransition();

  const load = useCallback(async () => {
    const r = await getTransferView(serverId);
    if (r.ok) setV(r);
  }, [serverId]);
  useEffect(() => { void load(); }, [load]);

  if (!v || !v.enabled) return null;
  const t: TransferView = v;

  const submit = () => start(async () => {
    setMsg(null);
    const r = await requestRegionTransfer(serverId, { toRegion: to, note, ackDowntime: ack });
    if (!r.ok) { setMsg({ ok: false, text: r.error }); return; }
    setMsg({ ok: true, text: "Request sent. We will review it and contact you to agree a time. Nothing moves until then." });
    setTo(""); setNote(""); setAck(false);
    await load();
  });

  return (
    <div className="card">
      <h3 className="font-semibold">Move to another location</h3>
      <p className="mt-1 text-sm text-slate-400">
        Want lower ping for your players? Ask us to move this server{t.fromLabel ? ` from ${t.fromLabel}` : ""} to another location.
        A request goes to our team, who agree a time with you before anything is moved.
      </p>

      {t.open ? (
        <div className="mt-4 rounded-xl border border-white/[0.08] bg-navy-950/60 p-3 text-sm">
          <p className="text-slate-200">Request to move to <b>{t.open.toLabel}</b>: {STATUS_TEXT[t.open.status] ?? t.open.status}.</p>
          {t.open.status === "REQUESTED" && (
            <button type="button" disabled={pending} className="mt-2 text-xs text-slate-400 underline hover:text-white"
              onClick={() => start(async () => { const r = await cancelRegionTransfer(t.open!.id); setMsg(r.ok ? { ok: true, text: "Request cancelled." } : { ok: false, text: r.error }); await load(); })}>
              Cancel this request
            </button>
          )}
        </div>
      ) : t.blocked ? (
        <p className="mt-4 text-sm text-slate-500">{t.blocked}</p>
      ) : t.targets.length === 0 ? (
        <p className="mt-4 text-sm text-slate-500">No other location is available for this server right now.</p>
      ) : (
        <div className="mt-4 space-y-3">
          <label className="block text-sm font-medium text-slate-300">
            Move to
            <select value={to} onChange={(e) => setTo(e.target.value)}
              className="mt-1 w-full rounded-xl border border-white/[0.08] bg-navy-950/60 px-3 py-2 text-sm text-slate-200">
              <option value="">Choose a location</option>
              {t.targets.map((r) => <option key={r.code} value={r.code}>{r.label}</option>)}
            </select>
          </label>
          <div className="rounded-xl border border-white/[0.08] bg-navy-950/60 p-3 text-sm text-slate-300">
            <p><b>Your server is offline while it moves:</b> {t.estimate.label}.{t.sizeGb != null ? ` It currently stores about ${t.sizeGb} GB.` : ""}</p>
            <p className="mt-1 text-xs text-slate-500">{t.estimate.basis} Create a backup from the Backups tab first.</p>
          </div>
          <label className="block text-sm font-medium text-slate-300">
            Anything we should know? <span className="text-xs text-slate-500">(optional)</span>
            <textarea value={note} onChange={(e) => setNote(e.target.value.slice(0, 500))} rows={2} maxLength={500}
              placeholder="Best times for your players, or a time to avoid"
              className="mt-1 w-full rounded-xl border border-white/[0.08] bg-navy-950/60 px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600" />
          </label>
          <label className="flex items-start gap-2 text-sm text-slate-300">
            <input type="checkbox" checked={ack} onChange={(e) => setAck(e.target.checked)} className="mt-1" />
            <span>I understand the server will be offline during the move, and I have a recent backup.</span>
          </label>
          <button type="button" disabled={pending || !to || !ack} onClick={submit}
            className="rounded-lg bg-brand-500/20 px-3 py-1.5 text-sm font-medium text-brand-200 transition hover:bg-brand-500/30 disabled:opacity-40">
            {pending ? "Sending…" : "Send request"}
          </button>
        </div>
      )}

      {t.recent.length > 0 && (
        <ul className="mt-4 space-y-1 text-xs text-slate-500">
          {t.recent.map((r) => (
            <li key={r.id}>{new Date(r.createdAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}: move to {r.toLabel}, {(STATUS_TEXT[r.status] ?? r.status).toLowerCase()}{r.adminNote ? ` (${r.adminNote})` : ""}</li>
          ))}
        </ul>
      )}
      {msg && <p className={`mt-3 text-xs ${msg.ok ? "text-emerald-400" : "text-red-400"}`}>{msg.text}</p>}
    </div>
  );
}
