      <PageHeader title="Transfer requests" sub="Customers asking to move a game server to another location. Approving does not move anything." />
      <div className="grid gap-4 sm:grid-cols-3">
        <StatCard label="Waiting" value={String(rows.filter((r) => r.status === "REQUESTED").length)} />
        <StatCard label="Approved" value={String(rows.filter((r) => r.status === "APPROVED").length)} />
        <StatCard label="Total" value={String(rows.length)} />
      </div>
      <TransferFlag on={on} />
      {rows.length === 0 && <EmptyState title="No requests" sub="Requests appear here once the customer card is switched on and a customer sends one." />}
      {rows.map((r) => (
        <div key={r.id} className="card space-y-2 p-4">
          <div className="flex flex-wrap items-center gap-2">
            <h3 className="text-sm font-semibold">{r.server.label || r.server.name}</h3>
            <Badge tone={tone(r.status)}>{r.status}</Badge>
            <span className="text-xs text-slate-400">{r.fromRegion ? customerRegionLabel(r.fromRegion) : "?"} to {customerRegionLabel(r.toRegion)}</span>
            <span className="text-xs text-slate-500">{r.server.user.email}</span>
            <Link className="text-xs underline text-slate-300" href={`/admin/servers/${r.server.id}`}>Open server (Move tab)</Link>
          </div>
          <p className="text-xs text-slate-400">
            {r.sizeGb != null ? `Stores about ${Math.round(r.sizeGb * 10) / 10} GB. ` : "Size unknown. "}
            {r.estimateMinutes ? `Estimate shown to customer: up to ${r.estimateMinutes} min offline. ` : "Estimate shown: range, size unknown. "}
            Customer acknowledged downtime and backup: {r.ackDowntime ? "yes" : "no"}. Requested {r.createdAt.toISOString().slice(0, 16).replace("T", " ")} UTC.
          </p>
          {r.customerNote && <p className="text-xs text-slate-300">Customer note: {r.customerNote}</p>}
          {r.adminNote && <p className="text-xs text-slate-400">Admin note: {r.adminNote}</p>}
          <TransferActions id={r.id} status={r.status} />
        </div>
      ))}
    </div>
  );
}
