  } catch (err) {
    return { ok: false, error: safeError(err) };
  } finally {
    if (lockKey) extracting.delete(lockKey);
  }
}

/** Run a fixed package-install command with a 5-minute cap; true on success. */
async function withInstallTimeout(
  conn: Parameters<Parameters<typeof withServerSsh>[1]>[0],
  cmd: string
): Promise<boolean> {
  try {
    const r = await exec(conn, cmd, 5 * 60_000);
    return r.code === 0;
  } catch {
    return false;
  }
}

