/**
 * Guided "Import my world" — pure rules (growth item prd-013). Client-safe (no
 * node/db imports) so the SAME classifier checks the customer's file picker and,
 * authoritatively, the real listing of what landed on their server.
 *
 * What each game accepts (and how it is placed):
 *   valheim   <name>.db + <name>.fwl (the classic pair), or a world FOLDER named
 *             <name> holding the .fwl/.db (the newer per-world folder saves).
 *             Placed in the server's worlds_local directory under <name>; the
 *             world setting is switched to <name> and the server restarts. A new
 *             name never touches the running world.
 *   minecraft a world folder containing level.dat (plus, optionally, its
 *             <name>_nether / <name>_the_end siblings). It REPLACES the server's
 *             current world folder; the old one is renamed aside, not deleted.
 *   terraria  one .wld file. It REPLACES the server's current world file; the old
 *             one is renamed aside, not deleted.
 * A .zip of any of the above is accepted too; the server unpacks it first and the
 * listing of the unpacked files is classified the same way.
 *
 * Reject, never repair: a wrong file set gets a plain message saying what is
 * missing; nothing is guessed or renamed behind the customer's back.
 */

export const WORLD_IMPORT_FAMILIES = ["valheim", "minecraft", "terraria"] as const;
export type WorldImportFamily = (typeof WORLD_IMPORT_FAMILIES)[number];
export const canImportWorld = (f: string | null | undefined): f is WorldImportFamily => (WORLD_IMPORT_FAMILIES as readonly string[]).includes(f ?? "");

/** The file manager's upload route accepts 250 MB per file; stay under it. */
export const MAX_FILE_BYTES = 250 * 1024 * 1024;
export const MAX_TOTAL_BYTES = 2 * 1024 ** 3;
export const MAX_FILES = 5000;

export type WorldFile = { path: string; size: number };

export type WorldPlan = {
  family: WorldImportFamily;
  kind: "valheim-pair" | "valheim-folder" | "minecraft-folder" | "terraria-file";
  /** Valheim: the world name the server will load. Others: the imported world's own name (informational). */
  worldName: string;
  /** What gets moved, relative to the staging root: [from, toName]. `toName` is a single path segment (or a suffix-mapped name for MC dimensions). */
  moves: { from: string; to: string; dir: boolean }[];
  totalBytes: number;
  fileCount: number;
  warnings: string[];
  /** Placing it replaces the world the server is running (needs the game stopped). */
  replacesActiveWorld: boolean;
};

export type WorldCheck = { ok: true; plan: WorldPlan } | { ok: false; errors: string[] };

export const VALHEIM_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9 _-]{0,39}$/;

const norm = (p: string) => p.replace(/\\/g, "/").replace(/^\.\//, "").replace(/\/+/g, "/");
const lower = (s: string) => s.toLowerCase();
const base = (p: string) => p.slice(p.lastIndexOf("/") + 1);
const stem = (n: string) => n.replace(/\.[^.]+$/, "");

/** Junk and backup files that are never part of an import (and never block one). */
const IGNORED = (name: string) => /^(\.DS_Store|Thumbs\.db|desktop\.ini|__MACOSX)$/i.test(name) || name.startsWith("._");

export function sizeProblems(files: WorldFile[]): string[] {
  const out: string[] = [];
  if (files.length > MAX_FILES) out.push(`That is ${files.length} files; the limit is ${MAX_FILES}. Zip the world folder and upload the zip instead.`);
  const big = files.find((f) => f.size > MAX_FILE_BYTES);
  if (big) out.push(`${base(big.path)} is larger than ${MAX_FILE_BYTES / 1024 / 1024} MB, the most one upload can carry. Use SFTP from the Access tab for a file this size.`);
  const total = files.reduce((a, f) => a + f.size, 0);
  if (total > MAX_TOTAL_BYTES) out.push(`The world is ${(total / 1024 ** 3).toFixed(1)} GB; the limit for a guided import is ${MAX_TOTAL_BYTES / 1024 ** 3} GB.`);
  return out;
}

/** Classify a candidate/staged file set for `family`. `files` paths are relative to the staging root. */
export function classifyWorld(family: WorldImportFamily, rawFiles: WorldFile[]): WorldCheck {
  const files = rawFiles
    .map((f) => ({ path: norm(f.path), size: f.size }))
    .filter((f) => !f.path.split("/").some(IGNORED));
  if (files.length === 0) return { ok: false, errors: ["No files were selected."] };
  const errors = sizeProblems(files);
  if (errors.length) return { ok: false, errors };
  const totalBytes = files.reduce((a, f) => a + f.size, 0);
  const warnings: string[] = [];

  if (family === "valheim") {
    // Classic pair at the top level (or one folder deep, from a zip that wrapped them).
    const top = topLevel(files);
    const flat = files.filter((f) => !f.path.includes("/") || f.path.split("/").length === 2 && top.single !== null && !f.path.slice(top.single.length + 1).includes("/") && f.path.startsWith(top.single + "/") && !isFolderSave(files, top.single));
    const dbs = flat.filter((f) => /\.db$/i.test(f.path) && !/_backup_/i.test(f.path));
    const fwls = flat.filter((f) => /\.fwl$/i.test(f.path) && !/_backup_/i.test(f.path));
    if (dbs.length || fwls.length) {
      if (dbs.length !== 1 || fwls.length !== 1) {
        return { ok: false, errors: [`A Valheim world is exactly one .db and one .fwl with the same name. Found ${dbs.length} .db and ${fwls.length} .fwl.`] };
      }
      const a = stem(base(dbs[0].path)), b = stem(base(fwls[0].path));
      if (a !== b) return { ok: false, errors: [`The .db and .fwl names must match (found "${a}" and "${b}"). Rename one so both are called the same, then try again.`] };
      if (!VALHEIM_NAME_RE.test(a)) return { ok: false, errors: [`"${a}" is not a usable world name. Use letters, numbers, spaces, - and _ (up to 40 characters), starting with a letter or number.`] };
      if (flat.some((f) => /_backup_/i.test(f.path)) || files.some((f) => /_backup_|\.old$/i.test(f.path))) warnings.push("Backup copies in the selection were skipped.");
      return {
        ok: true,
        plan: {
          family, kind: "valheim-pair", worldName: a, totalBytes: dbs[0].size + fwls[0].size, fileCount: 2, warnings, replacesActiveWorld: false,
          moves: [
            { from: dbs[0].path, to: `${a}.db`, dir: false },
            { from: fwls[0].path, to: `${a}.fwl`, dir: false },
          ],
        },
      };
    }
    // World folder save.
    if (top.single) {
      const inside = files.filter((f) => f.path.startsWith(top.single + "/"));
      if (isFolderSave(files, top.single)) {
        if (!VALHEIM_NAME_RE.test(top.single)) return { ok: false, errors: [`"${top.single}" is not a usable world name. Use letters, numbers, spaces, - and _ (up to 40 characters).`] };
        return {
          ok: true,
          plan: { family, kind: "valheim-folder", worldName: top.single, totalBytes, fileCount: inside.length, warnings, replacesActiveWorld: false, moves: [{ from: top.single, to: top.single, dir: true }] },
        };
      }
    }
    return { ok: false, errors: ["No Valheim world found. A world is a .db and .fwl pair with the same name (from your Valheim worlds_local folder), or a world folder holding them."] };
  }

  if (family === "minecraft") {
    const roots = worldRoots(files, "level.dat");
    if (roots.length === 0) return { ok: false, errors: ["No Minecraft world found: a world folder always contains a file called level.dat. Select the whole world folder (or a zip of it)."] };
