/** The file manager's upload route accepts 250 MB per file; stay under it. */
export const MAX_FILE_BYTES = 250 * 1024 * 1024;
export const MAX_TOTAL_BYTES = 2 * 1024 ** 3;
export const MAX_FILES = 5000;

export type WorldFile = { path: string; size: number };

export type WorldPlan = {
  family: WorldImportFamily;
  kind: "valheim-pair" | "valheim-folder" | "minecraft-folder" | "terraria-file";
  /** Valheim: the world name the server will load. Others: the imported world's own name (informational). */
  worldName: string;
  /** What gets moved, relative to the staging root: [from, toName]. `toName` is a single path segment (or a suffix-mapped name for MC dimensions). */
  moves: { from: string; to: string; dir: boolean }[];
  totalBytes: number;
  fileCount: number;
  warnings: string[];
  /** Placing it replaces the world the server is running (needs the game stopped). */
  replacesActiveWorld: boolean;
};

