    ok: true,
    plan: { family, kind: "terraria-file", worldName: stem(base(wlds[0].path)), totalBytes: wlds[0].size, fileCount: 1, warnings, replacesActiveWorld: true, moves: [{ from: wlds[0].path, to: "@wld", dir: false }] },
  };
