"use server";

/**
 * Guided "Import my world" (growth item prd-013) — the server half.
 *
 * Flow: the panel asks `getWorldImportInfo` for a private staging folder on the
 * customer's own server, uploads the picked files into it with the file
 * manager's existing upload route (and `extractArchive` for a .zip), then calls
 * `finalizeWorldImport`, which classifies what ACTUALLY landed (never the
 * browser's claim: lib/world-import.ts), moves it into place, switches the
 * world name where the game has one, and starts the game.
 *
 * Safety: the staging path is derived here from a validated random id, never
 * taken from the client; a world that would replace the running one is refused
 * unless the game is stopped; whatever it replaces is renamed aside
 * (`<name>.pre-import-<stamp>`), never deleted; a failed placement rolls the
 * renames back. Everything goes over the same SFTP the file manager uses, on
 * the customer's own VM, owner-checked.
 */
import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { recordAudit } from "./audit";
import { familyFor, validateConfig } from "./game-config";
import {
  listDir, statPath, renamePath, removePath, readFileText, joinPath, mkdirpPath, type SftpServer, type SftpEntry,
} from "./sftp";
import {
  canImportWorld, classifyWorld, resolveDestinations, asideSuffix, stagingName, IMPORT_ID_RE, WORLD_DIRS,
  type WorldImportFamily, type WorldPlan,
} from "./world-import";
import { getGameConfig, saveGameConfig } from "./actions-game-config";
import { gamePower } from "./actions-game-control";

type Fail = { ok: false; error: string };

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true, userId: true, status: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true,
      sshPort: true, guestSshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } },
      osTemplate: true, gamePlan: true, gameConfig: true, gameRuntime: { select: { state: true } },
    },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  return { user, server };
}

const fail = (e: unknown): Fail => ({
  ok: false,
  error: e instanceof Error && e.message === "Not found" ? "Server not found."
    : e instanceof Error && /^(Stop|The server|Your |This |No |Put|Pick|Too many|Choose)/.test(e.message) ? e.message
    : "Could not reach your server's files. Make sure it is running and try again.",
});

const throttle = (userId: string, op: string, max: number) => {
  const rl = checkRateLimit(`worldimport:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests. Retry in ${rl.retryAfterSec}s.`;
};

const GAME_UP = new Set(["online", "unverified", "starting", "not_responding", "crashed"]);
const gameMaybeRunning = (state: string | null | undefined) => !state || GAME_UP.has(state); // unknown counts as running: fail closed

async function firstDir(server: SftpServer, family: WorldImportFamily): Promise<string | null> {
  for (const d of WORLD_DIRS[family]) {
    try { if ((await statPath(server, d)).isDirectory) return d; } catch { /* next */ }
  }
  return null;
}

export type WorldImportInfo = {
  ok: true;
  family: WorldImportFamily;
  importId: string;
  stagingDir: string;
  /** Valheim: the world the server loads now. */
  currentWorld: string | null;
  gameRunning: boolean;
};

export async function getWorldImportInfo(serverId: string): Promise<WorldImportInfo | Fail> {
  try {
    const { user, server } = await ownedServer(serverId);
    const family = familyFor(server);
    if (!canImportWorld(family)) return { ok: false, error: "World import is available for Valheim, Minecraft and Terraria servers." };
    if (server.status !== "RUNNING") return { ok: false, error: "Your server needs to be running to import a world. Start it first." };
    const limited = throttle(user.id, "info", 20);
    if (limited) return { ok: false, error: limited };
    const dir = await firstDir(server as SftpServer, family);
    if (!dir) return { ok: false, error: "Could not find where your server keeps its worlds. Contact support and we will sort it out." };
    const importId = randomBytes(9).toString("hex").slice(0, 12);
    const cfg = validateConfig(family, (server.gameConfig as Record<string, unknown> | null) ?? {});
    return {
      ok: true, family, importId, stagingDir: joinPath(dir, stagingName(importId)),
      currentWorld: family === "valheim" && cfg.ok ? String(cfg.values.world ?? "") || null : null,
      gameRunning: gameMaybeRunning(server.gameRuntime?.state),
    };
  } catch (e) { return fail(e); }
}

/** Every file under `dir` (relative paths), bounded. */
async function walk(server: SftpServer, dir: string, rel = "", depth = 0, acc: { path: string; size: number }[] = []): Promise<{ path: string; size: number }[]> {
  if (depth > 6 || acc.length > 6000) return acc;
  let ents: SftpEntry[];
  try { ents = await listDir(server, rel ? joinPath(dir, rel) : dir); } catch { return acc; }
  for (const e of ents) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory) await walk(server, dir, r, depth + 1, acc);
    else acc.push({ path: r, size: e.size });
  }
  return acc;
}

const exists = async (s: SftpServer, p: string) => { try { await statPath(s, p); return true; } catch { return false; } };

export type FinalizeResult =
  | { ok: true; worldName: string; replaced: string[]; started: boolean; note: string; warnings: string[] }
  | Fail;

export async function finalizeWorldImport(serverId: string, importId: string): Promise<FinalizeResult> {
  try {
    if (!IMPORT_ID_RE.test(importId)) return { ok: false, error: "This import session is no longer valid. Start the import again." };
    const { user, server } = await ownedServer(serverId);
    const family = familyFor(server);
    if (!canImportWorld(family)) return { ok: false, error: "World import is not available for this game." };
    if (server.status !== "RUNNING") return { ok: false, error: "Your server needs to be running to import a world." };
    const limited = throttle(user.id, "finalize", 6);
    if (limited) return { ok: false, error: limited };
    const sftp = server as SftpServer;

    const dir = await firstDir(sftp, family);
    if (!dir) return { ok: false, error: "Could not find where your server keeps its worlds." };
    const staging = joinPath(dir, stagingName(importId));
    if (!(await exists(sftp, staging))) return { ok: false, error: "Nothing was uploaded for this import. Choose your files and upload them first." };
    // A .zip is unpacked into <staging>/unpacked by the panel (extractArchive); classify that if present.
    const root = (await exists(sftp, joinPath(staging, "unpacked"))) ? joinPath(staging, "unpacked") : staging;
    const listed = (await walk(sftp, root)).filter((f) => !/\.zip$/i.test(f.path) || f.path.includes("/"));
    const check = classifyWorld(family, listed);
    if (!check.ok) return { ok: false, error: check.errors.join(" ") };
    const plan: WorldPlan = check.plan;

    // The running world must not be swapped from under the game.
    const running = gameMaybeRunning(server.gameRuntime?.state);
    let levelName = "world";
    let terrariaFile = "nxeon.wld";
    if (family === "minecraft") {
      try {
        const props = await readFileText(sftp, joinPath(dir, "server.properties"), 64 * 1024);
        const m = /^level-name=(.*)$/m.exec(props);
        if (m && /^[A-Za-z0-9 _.-]{1,64}$/.test(m[1].trim())) levelName = m[1].trim();
      } catch { /* default */ }
    }
    if (family === "terraria") {
      try {
        const cur = (await listDir(sftp, dir)).find((e) => !e.isDirectory && /\.wld$/i.test(e.name));
        if (cur) terraria_set(cur.name);
      } catch { /* default */ }
    }
    function terraria_set(n: string) { terrariaFile = n; }
    const moves = resolveDestinations(plan, { levelName, terrariaFile });
    const conflicts: string[] = [];
    for (const m of moves) if (await exists(sftp, joinPath(dir, m.to))) conflicts.push(m.to);
    if ((plan.replacesActiveWorld || conflicts.length) && running) {
      throw new Error(`Stop the server first (power controls at the top of the panel), then finish the import. ${plan.replacesActiveWorld ? "This import replaces the world the server is running" : "A world with this name already exists"} and must not be swapped while the game is running.`);
    }

    // Rename what is in the way aside, then move the new files in; roll back on any failure.
    const suffix = asideSuffix();
    const asides: { orig: string; aside: string }[] = [];
    const placed: string[] = [];
    try {
      for (const to of conflicts) {
        const orig = joinPath(dir, to);
        const aside = `${orig}.${suffix}`;
        await renamePath(sftp, orig, aside);
        asides.push({ orig, aside });
      }
      for (const m of moves) {
        const dest = joinPath(dir, m.to);
        await renamePath(sftp, joinPath(root, m.from), dest);
        placed.push(dest);
      }
    } catch (err) {
      for (const p of placed.reverse()) await renamePath(sftp, p, joinPath(root, p.slice(dir.length + 1))).catch(() => {});
      for (const a of asides.reverse()) await renamePath(sftp, a.aside, a.orig).catch(() => {});
      throw new Error("Could not place the world files, so nothing was changed. Please try again or contact support.");
    }
    await removePath(sftp, staging).catch(() => {});

    const notes: string[] = [];
    let started = false;
    if (family === "valheim") {
      const cfg = await getGameConfig(serverId);
      if (cfg.config) {
        const save = await saveGameConfig(serverId, cfg.config.variant, { ...cfg.config.values, world: plan.worldName }, { restart: true });
        if (save.ok) { started = true; notes.push(`The server is restarting onto "${plan.worldName}". Your previous world stays on disk and returns if you switch the World name back.`); }
