 * manager's existing upload route (and `extractArchive` for a .zip), then calls
 * `finalizeWorldImport`, which classifies what ACTUALLY landed (never the
 * browser's claim: lib/world-import.ts), moves it into place, switches the
 * world name where the game has one, and starts the game.
 *
 * Safety: the staging path is derived here from a validated random id, never
 * taken from the client; a world that would replace the running one is refused
 * unless the game is stopped; whatever it replaces is renamed aside
 * (`<name>.pre-import-<stamp>`), never deleted; a failed placement rolls the
 * renames back. Everything goes over the same SFTP the file manager uses, on
 * the customer's own VM, owner-checked.
 */
import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { recordAudit } from "./audit";
import { familyFor, validateConfig } from "./game-config";
