"use client";

import { useRef, useState } from "react";
import {
  canImportWorld, classifyWorld, type WorldCheck, type WorldFile, type WorldImportFamily,
} from "@/lib/world-import";
import { getWorldImportInfo, finalizeWorldImport, cancelWorldImport } from "@/lib/actions-world-import";
import { extractArchive } from "@/lib/actions-files";

/**
 * "Import my world" wizard (growth item prd-013): pick files → we check them →
 * upload → place them, set the world name and restart. The checks here only
 * save a failed upload; the authoritative check runs again on the files that
 * really landed on the server (lib/actions-world-import.ts).
 */
const WHAT: Record<WorldImportFamily, { title: string; accepts: string; where: string }> = {
  valheim: { title: "Valheim", accepts: "a .db and .fwl pair with the same name (or a world folder)", where: "Windows: %USERPROFILE%\\AppData\\LocalLow\\IronGate\\Valheim\\worlds_local" },
  minecraft: { title: "Minecraft", accepts: "a world folder (the one with level.dat inside)", where: "Singleplayer worlds: the .minecraft/saves folder" },
  terraria: { title: "Terraria", accepts: "one .wld file", where: "Windows: Documents\\My Games\\Terraria\\Worlds" },
};

type Picked = { file: File; rel: string };
const mb = (n: number) => (n >= 1024 ** 3 ? `${(n / 1024 ** 3).toFixed(1)} GB` : `${Math.max(1, Math.round(n / 1024 ** 2))} MB`);

export function GameWorldImport({ serverId, family, gameRunning }: { serverId: string; family: string; gameRunning: boolean }) {
  const [picked, setPicked] = useState<Picked[]>([]);
  const [check, setCheck] = useState<WorldCheck | null>(null);
  const [isZip, setIsZip] = useState(false);
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState<string | null>(null);
  const [result, setResult] = useState<{ ok: boolean; text: string; warnings?: string[] } | null>(null);
  const filesRef = useRef<HTMLInputElement>(null);
  const folderRef = useRef<HTMLInputElement>(null);
  if (!canImportWorld(family)) return null;
  const w = WHAT[family];

  const onPick = (list: FileList | null) => {
    setResult(null);
    if (!list || list.length === 0) { setPicked([]); setCheck(null); return; }
    const items: Picked[] = Array.from(list).map((f) => ({ file: f, rel: (f as File & { webkitRelativePath?: string }).webkitRelativePath || f.name }));
    setPicked(items);
    const zip = items.length === 1 && /\.zip$/i.test(items[0].file.name);
    setIsZip(zip);
    setCheck(zip ? null : classifyWorld(family, items.map((p): WorldFile => ({ path: p.rel, size: p.file.size }))));
  };

  const ready = picked.length > 0 && (isZip ? picked[0].file.size > 0 : check?.ok === true);
  const plan = check && check.ok ? check.plan : null;
  const blockedByRunning = gameRunning && (plan?.replacesActiveWorld ?? (isZip && family !== "valheim"));

  async function run() {
    setBusy(true); setResult(null);
    let importId: string | null = null;
    try {
      setProgress("Preparing your server…");
      const info = await getWorldImportInfo(serverId);
      if (!info.ok) { setResult({ ok: false, text: info.error }); return; }
      importId = info.importId;
      const queue = picked;
      for (let i = 0; i < queue.length; i++) {
        setProgress(`Uploading ${i + 1} of ${queue.length}: ${queue[i].file.name} (${mb(queue[i].file.size)})`);
        const fd = new FormData();
        fd.append("file", queue[i].file);
        if (!isZip) fd.append("relPath", queue[i].rel);
        const res = await fetch(`/api/files/${serverId}?path=${encodeURIComponent(info.stagingDir)}`, { method: "POST", body: fd });
        if (!res.ok) {
          const j = await res.json().catch(() => ({}));
          setResult({ ok: false, text: `Upload failed: ${(j as { error?: string }).error ?? res.status}` });
          await cancelWorldImport(serverId, info.importId);
          return;
        }
      }
      if (isZip) {
        setProgress("Unpacking the zip on your server…");
        const ex = await extractArchive(serverId, `${info.stagingDir}/${picked[0].file.name.replace(/[^\w.() -]/g, "_")}`, `${info.stagingDir}/unpacked`, true);
        if (!ex.ok) { setResult({ ok: false, text: ex.error }); await cancelWorldImport(serverId, info.importId); return; }
      }
      setProgress("Checking and placing your world…");
      const fin = await finalizeWorldImport(serverId, info.importId);
      if (!fin.ok) { setResult({ ok: false, text: fin.error }); await cancelWorldImport(serverId, info.importId); return; }
      setResult({ ok: true, text: `"${fin.worldName}" imported. ${fin.note}`, warnings: fin.warnings });
      setPicked([]); setCheck(null);
    } catch {
      setResult({ ok: false, text: "Something went wrong during the import. Nothing was changed on your world. Please try again." });
      if (importId) await cancelWorldImport(serverId, importId).catch(() => {});
    } finally {
      setBusy(false); setProgress(null);
    }
  }

  return (
    <div className="card">
      <h3 className="font-semibold">Import my {w.title} world</h3>
      <p className="mt-1 text-sm text-slate-400">
        Bring a world from your own computer or another host. Choose {w.accepts}, or a .zip of it. {w.where}.
      </p>
      <ol className="mt-3 list-decimal space-y-1 pl-5 text-xs text-slate-400">
        <li>Create a backup in the section above if you want a restore point.</li>
        <li>Pick your files. We check them before anything is uploaded.</li>
        <li>We place the world{family === "valheim" ? ", switch the World name to it" : ""} and start the server.{family !== "valheim" && " The world it replaces is kept, renamed, in your Files."}</li>
      </ol>

      <div className="mt-4 flex flex-wrap gap-2">
        <input ref={filesRef} type="file" multiple className="hidden" onChange={(e) => onPick(e.target.files)} />
        <input ref={folderRef} type="file" className="hidden" onChange={(e) => onPick(e.target.files)}
          {...({ webkitdirectory: "", directory: "" } as Record<string, string>)} />
        <button type="button" disabled={busy} onClick={() => filesRef.current?.click()} className="btn-ghost text-xs">Choose files or a .zip</button>
        {family !== "terraria" && <button type="button" disabled={busy} onClick={() => folderRef.current?.click()} className="btn-ghost text-xs">Choose a world folder</button>}
      </div>

      {picked.length > 0 && (
        <div className="mt-3 rounded-xl border border-white/[0.08] bg-navy-950/60 p-3 text-sm">
          {isZip ? (
            <p className="text-slate-300">{picked[0].file.name} ({mb(picked[0].file.size)}). We unpack it on your server and check what is inside before placing anything.</p>
          ) : check && check.ok ? (
            <>
              <p className="text-slate-200">Found {family === "valheim" ? "Valheim world" : family === "minecraft" ? "Minecraft world" : "Terraria world"} <b>{check.plan.worldName}</b>: {check.plan.fileCount} file{check.plan.fileCount === 1 ? "" : "s"}, {mb(check.plan.totalBytes)}.</p>
              {check.plan.warnings.map((x, i) => <p key={i} className="mt-1 text-xs text-amber-300">{x}</p>)}
            </>
          ) : check ? (
            check.errors.map((x, i) => <p key={i} className="text-red-300">{x}</p>)
          ) : null}
        </div>
      )}

      {blockedByRunning && ready && (
        <p className="mt-3 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
          This import replaces the world the server is running. Stop the server with the power controls at the top of the panel first, then press Import.
        </p>
      )}

      <div className="mt-4 flex items-center gap-3">
        <button type="button" disabled={!ready || busy || blockedByRunning} onClick={run}
          className="rounded-lg bg-brand-500/20 px-3 py-1.5 text-sm font-medium text-brand-200 transition hover:bg-brand-500/30 disabled:opacity-40">
          {busy ? "Importing…" : "Import this world"}
        </button>
        {progress && <span className="text-xs text-slate-400">{progress}</span>}
      </div>

      {result && (
        <div className={`mt-3 text-sm ${result.ok ? "text-emerald-400" : "text-red-400"}`}>
          <p>{result.text}</p>
          {result.warnings?.map((x, i) => <p key={i} className="mt-1 text-xs text-amber-300">{x}</p>)}
        </div>
      )}
    </div>
  );
}
