const WHAT: Record<WorldImportFamily, { title: string; accepts: string; where: string }> = {
  valheim: { title: "Valheim", accepts: "a .db and .fwl pair with the same name (or a world folder)", where: "Windows: %USERPROFILE%\\AppData\\LocalLow\\IronGate\\Valheim\\worlds_local" },
  minecraft: { title: "Minecraft", accepts: "a world folder (the one with level.dat inside)", where: "Singleplayer worlds: the .minecraft/saves folder" },
  terraria: { title: "Terraria", accepts: "one .wld file", where: "Windows: Documents\\My Games\\Terraria\\Worlds" },
};

