    setResult(null);
    if (!list || list.length === 0) { setPicked([]); setCheck(null); return; }
    const items: Picked[] = Array.from(list).map((f) => ({ file: f, rel: (f as File & { webkitRelativePath?: string }).webkitRelativePath || f.name }));
    setPicked(items);
    const zip = items.length === 1 && /\.zip$/i.test(items[0].file.name);
