      setProgress("Preparing your server…");
      const info = await getWorldImportInfo(serverId);
      if (!info.ok) { setResult({ ok: false, text: info.error }); return; }
      importId = info.importId;
      const queue = picked;
      for (let i = 0; i < queue.length; i++) {
        setProgress(`Uploading ${i + 1} of ${queue.length}: ${queue[i].file.name} (${mb(queue[i].file.size)})`);
