      </div>

      {result && (
        <div className={`mt-3 text-sm ${result.ok ? "text-emerald-400" : "text-red-400"}`}>
          <p>{result.text}</p>
          {result.warnings?.map((x, i) => <p key={i} className="mt-1 text-xs text-amber-300">{x}</p>)}
        </div>
      )}
    </div>
  );
}
